public class Solution {
    public int findTheWinner(int n, int k) {
        List<Integer> friends = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            friends.add(i);
        }
        return helper(friends, k, 0);
    }

    private int helper(List<Integer> friends, int k, int index) {
        if (friends.size() == 1) {
