public class Solution {
    public int lenLongestFibSubseq(int[] arr) {
        int n = arr.length;
        int maxNum = Integer.MAX_VALUE / 2;
        boolean[] exist = new boolean[maxNum + 1];
        for (int num : arr) {
            exist[num] = true;
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long a = arr[i], b = arr[j];
                int len = 2;
                while (a <= maxNum && exist[(int) a + (int) b]) {
                    int next = (int) (a + b);
                    a = b;
