import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Map<String, Integer> dir = new HashMap<>();
        dir.put("right", 0);
        dir.put("up", 1);
        dir.put("left", 2);
        dir.put("down", 3);

        double x = 0;
        double y = 0;
        int maxDist = 0;

        for (int i = 0; i < commands.length; i++) {
            if (commands[i] == -2) {
                String currDir = getDirection(x, y);
                int newDir = dir.get(currDir) - 1;
                if (newDir < 0) newDir += 4;
                dir.put(currDir, newDir);
            } else if (commands[i] == -1) {
                String currDir = getDirection(x, y);
                int newDir = dir.get(currDir) + 1;
                if (newDir > 3) newDir -= 4;
                dir.put(currDir, newDir);
            } else {
                double newX = x + commands[i] * Math.cos(Math.toRadians(dir.get(getDirection(x, y))));
                double newY = y + commands[i] * Math.sin(Math.toRadians(dir.get(getDirection(x, y))));

                if (isObstacle(newX, newY, obstacles)) {
                    continue;
                }

                x = newX;
                y = newY;

                maxDist = Math.max(maxDist, x * x + y * y);
            }
        }

        return (int) maxDist;
    }

    private String getDirection(double x, double y) {
        if (x > 0 && y >= 0) return "right";
        else if (x == 0 && y > 0) return "up";
        else if (x < 0 && y > 0) return "left";
        else if (x <= 0 && y == 0) return "down";
        else if (x < 0 && y <= 0) return "right";
        else if (x == 0 && y < 0) return "down";
        else if (x > 0 && y <= 0) return "left";
    }

    private boolean isObstacle(double x, double y, int[][] obstacles) {
        for (int[] obstacle : obstacles) {
            if (Math.abs(x - obstacle[0]) < 1e-6 && Math.abs(y - obstacle[1]) < 1e-6) return true;
        }
        return false;
    }
}

