import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int count = 0;
        for (int i = 0; i < grid.length - 2; i++) {
            for (int j = 0; j < grid[0].length - 2; j++) {
                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagicSquare(int[][] grid, int row, int col) {
        Set<Integer> numbers = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[row + i][col + j] <= 9 && grid[row + i][col + j] >= 1) {
                    numbers.add(grid[row + i][col + j]);
                } else {
                    return false;
                }
            }
        }

        int sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += grid[row][col + i];
            sum += grid[row + 2][col + i];
        }
        if (sum != 15) return false;

        sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += grid[row + i][col];
            sum += grid[row + i][col + 2];
        }
        if (sum != 15) return false;

        sum = grid[row][col] + grid[row + 1][col + 1] + grid[row + 2][col + 2];
        if (sum != 15) return false;

        sum = grid[row + 2][col] + grid[row + 1][col + 1] + grid[row][col + 2];
        if (sum != 15) return false;

        return numbers.size() == 9;
    }
}

