public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int totalSurfaceArea = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    totalSurfaceArea += 4 * grid[i][j];
                    if (i > 0 && grid[i - 1][j] > 0) {
                        totalSurfaceArea -= 2;
                    }
                    if (j > 0 && grid[i][j - 1] > 0) {
                        totalSurfaceArea -= 2;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 1 && grid[i - 1][j] > 0) {
                    totalSurfaceArea += 2;
                }
                if (grid[i][j] > 1 && grid[i][j - 1] > 0) {
                    totalSurfaceArea += 2;
                }
            }
        }

        return totalSurfaceArea;
    }
}

