public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                reverseRow(grid, i);
            }
        }

        for (int j = 1; j < n; j++) {
            int count = 0;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 0) {
                    count++;
                }
            }
            if (count * 2 >= m) {
                reverseCol(grid, j);
            }
        }

        int score = 0;
        for (int i = 0; i < m; i++) {
            score += grid[i][0];
            for (int j = 1; j < n; j++) {
                score = score * 2 + grid[i][j];
            }
        }

        return score;
    }

    private void reverseRow(int[][] grid, int row) {
        for (int i = 0; i < grid[row].length; i++) {
            if (grid[row][i] == 1) {
                grid[row][i] = 0;
            } else {
                grid[row][i] = 1;
            }
        }
    }

    private void reverseCol(int[][] grid, int col) {
        for (int i = 0; i < grid.length; i++) {
            if (grid[i][col] == 1) {
                grid[i][col] = 0;
            } else {
                grid[i][col] = 1;
            }
        }
    }
}

