public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] answer = new int[n];
        int[] count = new int[n];

        dfs(graph, 0, -1, answer, count);

        return answer;
    }

    private void dfs(List<Integer>[] graph, int node, int parent, int[] answer, int[] count) {
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(graph, child, node, answer, count);
                answer[node] += answer[child];
                count[node] += count[child] + 1;
            }
        }

        answer[node] = n - count[node];
    }
}

