public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }

        long ans = 0;
        for (int i : set) {
            for (int j : set) {
                if (i == j) continue;
                int and = i & j, or = i | j;
                int cnt1 = countOnes(and), cnt2 = countOnes(or);
                if (cnt1 + cnt2 >= k) ans++;
            }
        }

        return ans;
    }

    private int countOnes(int n) {
        int cnt = 0;
        while (n > 0) {
            cnt += n & 1;
            n >>= 1;
        }
        return cnt;
    }
}

