public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        long ans = 0, prev = (long)nums[n-1];
        for (int i=n-2; i>=0; --i) {
            if (nums[i] >= prev) return -1;
            long cnt = 1, tmp = nums[i];
            for (int j=i+1; j<n && tmp<prev; ++j) {
                if (tmp*2 <= nums[j]) {
                    ans += cnt-1;
                    cnt = 1;
                    tmp = nums[j];
                } else {
                    ++cnt;
                    tmp += nums[j];
                }
            }
            prev = nums[i];
        }
        return ans;
    }
}

