public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0, sum2 = 0;
        for (int i : nums1) sum1 += i;
        for (int i : nums2) sum2 += i;

        long maxEndingHere = Long.MIN_VALUE, minEndingHere = Long.MAX_VALUE;
        long maxSoFar = Long.MIN_VALUE, minSoFar = Long.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            if (sum1 >= sum2) {
                maxEndingHere = Math.max(maxEndingHere, sum1 - nums1[i] + nums2[i]);
                minEndingHere = Math.min(minEndingHere, sum1 - nums1[i] + nums2[i]);

                maxSoFar = Math.max(maxSoFar, maxEndingHere);
                minSoFar = Math.min(minSoFar, minEndingHere);

                sum1 -= nums1[i];
                sum2 += nums2[i];
            } else {
                maxEndingHere = Math.max(maxEndingHere, sum2 - nums2[i] + nums1[i]);
                minEndingHere = Math.min(minEndingHere, sum2 - nums2[i] + nums1[i]);

                maxSoFar = Math.max(maxSoFar, maxEndingHere);
                minSoFar = Math.min(minSoFar, minEndingHere);

                sum1 += nums1[i];
                sum2 -= nums2[i];
            }
        }

        return (int) Math.max(Math.max(maxSoFar, -minSoFar), Math.max(sum1, sum2));
    }
}

