            total += travel[i];

            if (garbage[i].contains("M")) {
                metal -= count(garbage[i], 'M');
            }
            if (garbage[i].contains("P")) {
                paper -= count(garbage[i], 'P');
            }
            if (garbage[i].contains("G")) {
                glass -= count(garbage[i], 'G');
            }
        }

        return (int) total;
    }

