        for (String idea : ideas) {
            char firstChar = idea.charAt(0);
            if (!map.containsKey(firstChar)) {
                map.put(firstChar, new HashSet<>());
            }
            map.get(firstChar).add(idea);
        }

        int count = 0;
        for (Map.Entry<Character, Set<String>> entry1 : map.entrySet()) {
            char firstCharA = entry1.getKey();
            Set<String> setA = entry1.getValue();

            for (Map.Entry<Character, Set<String>> entry2 : map.entrySet()) {
                if (entry2.getKey() != firstCharA) {
                    char firstCharB = entry2.getKey();
                    Set<String> setB = entry2.getValue();

                    int countAB = 0;
                    for (String ideaA : setA) {
                        String ideaB = null;
                        for (String idea : setB) {
                            if (!idea.equals(ideaA)) {
                                ideaB = idea;
                                break;
                            }
                        }

                        if (ideaB != null && !map.get(firstCharA).contains(ideaB + " " + ideaA) && !map.get(firstCharB).contains(ideaA + " " + ideaB)) {
                            countAB++;
                        }
                    }

                    int countBA = 0;
                    for (String ideaB : setB) {
                        String ideaA = null;
                        for (String idea : setA) {
                            if (!idea.equals(ideaB)) {
                                ideaA = idea;
                                break;
                            }
                        }

                        if (ideaA != null && !map.get(firstCharA).contains(ideaB + " " + ideaA) && !map.get(firstCharB).contains(ideaA + " " + ideaB)) {
                            countBA++;
                        }
                    }

                    count += Math.max(countAB, countBA);
                }
            }
        }

        return count;
    }
}

