public class Solution {
    public long countSubarrays(int[] nums, long k) {
        int n = nums.length;
        long sum = 0;
        long ans = 0;

        for (int i = 0; i < n; i++) {
            sum += nums[i];
            if (sum >= k) continue;

            for (int j = i + 1; j <= n; j++) {
                if (j > n) break;
                sum += nums[j];
                if (sum >= k) break;
                ans++;
            }
        }

        return ans;
    }
}

