public class Solution {
    public int fillCups(int[] amount) {
        Arrays.sort(amount);
        int seconds = 0;

        while (amount[2] > 0 && amount[1] > 0) {
            if (amount[0] < amount[2]) {
                amount[0]++;
                amount[2]--;
            } else {
                amount[1]++;
                amount[0]--;
            }
            seconds++;
        }

        while (amount[1] > 0 || amount[0] > 0) {
            if (amount[0] > 0 && amount[1] == 0) {
                amount[2]++;
                amount[0]--;
            } else if (amount[1] > 0 && amount[0] == 0) {
                amount[2]++;
                amount[1]--;
            } else {
                int min = Math.min(amount[0], amount[1]);
                amount[2] += min * 2;
                amount[0] -= min;
                amount[1] -= min;
            }
            seconds++;
        }

        return seconds;
    }
}

