public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;
        boolean[] selected = new boolean[n];

        return helper(matrix, numSelect, 0, m, selected);
    }

    private int helper(int[][] matrix, int numSelect, int start, int m, boolean[] selected) {
        if (numSelect == 0) {
            int count = 0;
            for (int i = 0; i < m; i++) {
                boolean isCovered = true;
                for (int j = 0; j < matrix[i].length; j++) {
                    if (matrix[i][j] == 1 && !selected[j]) {
                        isCovered = false;
                        break;
                    }
                }
                if (isCovered) count++;
            }
            return count;
        }

        int maxCount = 0;
        for (int i = start; i < matrix[0].length; i++) {
            selected[i] = true;
            maxCount = Math.max(maxCount, helper(matrix, numSelect - 1, i + 1, m, selected));
            selected[i] = false;
        }

        return maxCount;
    }
}

