public class Solution {
    Map<String, Long> memo = new HashMap<>();

    public long sellingWood(int m, int n, int[][] prices) {
        return dp(m, n);
    }

    private long dp(int m, int n) {
        if (m == 0 || n == 0)
            return 0;

        String key = m + "," + n;
        if (memo.containsKey(key))
            return memo.get(key);

        long maxProfit = 0;
        for (int[] price : prices) {
            int h = price[0], w = price[1];
            if (h <= m && w <= n)
                maxProfit = Math.max(maxProfit, dp(m - h, n) + dp(m, n - w));
        }

        memo.put(key, maxProfit);
        return maxProfit;
    }
}

