public class Solution {
    public int countHousePlacements(int n) {
        long MOD = (long) 1e9 + 7;
        long[][] dp = new long[n + 1][2];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            dp[i][0] = (dp[i - 1][0] * 2) % MOD;
            dp[i][1] = ((dp[i - 1][0] + dp[i - 1][1]) * dp[i - 1][0]) % MOD;
        }
