public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        for (int i = 0; i < buses.length - 1; i++) {
            if (buses[i + 1] - buses[i] <= capacity) {
                return buses[i];
            }
        }

        int lastBusDepartureTime = buses[buses.length - 1];

        int lastPassengerArrivalTime = passengers[passengers.length - 1];

        for (int i = passengers.length - 2; i >= 0; i--) {
            if (lastPassengerArrivalTime - passengers[i] <= capacity) {
                return passengers[i];
            }
        }

        return lastBusDepartureTime;
    }
}

