public class Solution {
    public int unequalTriplets(int[] nums) {
        Arrays.sort(nums);
        long count = 0;
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i-1]) continue;
            int j = i + 1, k = nums.length - 1;
            while (j < k) {
                if (nums[j] == nums[k]) {
                    j++;
                    k--;
                    continue;
                }
                count += k - j;
                j++;
                k--;
            }
        }
        return (int)count;
    }
