        int n = grid[0].length;

        // Initialize the result with negative infinity
        int res = Integer.MIN_VALUE;

        for (int i = 1; i < m - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                // Check if an hour glass can be formed from the current position
                if (grid[i-1][j] + grid[i+1][j] + grid[i][j-1] + grid[i][j+1] + grid[i][j] >= 0) {
                    res = Math.max(res, 
                        // Traverse the bottom and the top row of the hour glass at the same time
                        // Add the middle value
                        (grid[i-1][j] + grid[i+1][j]) + (grid[i][j-1] + grid[i][j+1]) + grid[i][j]);
                }
            }
        }

        return res;
    }
