public class Solution {
    public int deleteString(String s) {
        Map<String, Integer> map = new HashMap<>();
        int n = s.length();
        for (int i = 1; i <= n / 2; i++) {
            String substr = s.substring(0, i);
            if (s.startsWith(substr, i)) {
                map.put(substr, Math.max(map.getOrDefault(substr, 0), (n + 1) / (i + 1)));
