    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int maxOr = 0, windowStart = i;
            for (int j = i; j < n; j++) {
                maxOr |= nums[j];
                while (windowStart <= j && maxOr == nums[windowStart]) {
                    windowStart++;
