import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        Map<Integer, Integer> count = new HashMap<>();

        for (int num : nums) {
            int remainder = num % space;

            if (!count.containsKey(remainder)) {
                count.put(remainder, 1);
            } else {
                count.put(remainder, count.get(remainder) + 1);
            }
        }

        int maxCount = 0;
        int minNum = Integer.MAX_VALUE;

        for (int num : nums) {
            int remainder = num % space;

            if (count.containsKey(remainder)) {
                if (count.get(remainder) > maxCount) {
                    maxCount = count.get(remainder);
                    minNum = Math.min(minNum, num);
                } else if (count.get(remainder) == maxCount && num < minNum) {
                    minNum = num;
                }
            }
        }

        return minNum;
    }
}

