public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i : nodeValues) {
            map.put(i, 0);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] == b[1] ? b[0] - a[0] : b[1] - a[1]);

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            pq.offer(new int[]{u, nodeValues[u] + nodeValues[v]});
            map.put(u, Math.max(map.get(u), nodeValues[u] + nodeValues[v]));
            map.put(v, Math.max(map.get(v), nodeValues[u] + nodeValues[v]));
        }

        int ans = Integer.MIN_VALUE;
        for (int i = 0; i < maxNumberOfEdges && !pq.isEmpty(); i++) {
            int[] edge = pq.poll();
            ans = Math.max(ans, map.get(edge[0]) + edge[1]);
        }

        return ans;
    }
}

