import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final Set<Character> PRIME_DIGITS = new HashSet<>(Arrays.asList('2', '3', '5', '7'));

    public int beautifulPartitions(String s, int k, int minLength) {
        long[] dp = new long[s.length() + 1];
        Arrays.fill(dp, -1);
        return (int) dfs(s, k, minLength, 0, dp);
    }

    private long dfs(String s, int k, int minLength, int index, long[] dp) {
        if (index == s.length()) {
            return k == 0 ? 1 : 0;
        }
        if (dp[index] != -1) {
            return dp[index];
        }
        long res = 0;
        for (int i = index + minLength; i <= s.length(); i++) {
            char start = s.charAt(index);
            char end = s.charAt(i - 1);
            if (!PRIME_DIGITS.contains(start) || PRIME_DIGITS.contains(end)) {
                continue;
            }
            res += dfs(s, k - 1, minLength, i, dp);
        }
        return dp[index] = res % MOD;
    }
}

