import java.util.*;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        long[] value = new long[n];

        dfs(0, -1, graph, nums, parent, value);

        long totalSum = 0;
        for (int i = 0; i < n; i++) {
            totalSum += value[i];
        }

        int maxComponents = 0;
        for (long v : value) {
            if (v == 0) continue;
            maxComponents++;
        }

        return Math.max(0, n - maxComponents);
    }

    private void dfs(int node, int parent, List<Integer>[] graph, int[] nums, int[] parentArr, long[] valueArr) {
        for (int child : graph[node]) {
            if (child == parent) continue;
            parentArr[child] = node;
            valueArr[child] = nums[child];
            dfs(child, node, graph, nums, parentArr, valueArr);
            valueArr[node] += valueArr[child];
        }
    }
}

