public class Solution {
    public int equalizeArray(int[] nums, int[] cost) {
        int n = nums.length;
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(nums[i]);
        }
        list.sort(Comparator.naturalOrder());
        long totalCost = 0;
        for (int i = 0; i < n; i++) {
            int diff = list.get(n - 1) - list.get(i);
            if (diff == 0) continue;
            int minCost = Integer.MAX_VALUE;
            for (int j = 0; j <= i; j++) {
                long temp = Math.abs(list.get(j) - list.get(i)) * cost[j];
                minCost = Math.min(minCost, temp);
            }
            totalCost += minCost;
        }
        return (int)totalCost;
    }
}

