    public Solution(int[] nums, int k) {
        this.nums = nums;
        this.k = k;
    }

    public int longestSubsequence() {
        if (nums.length == 0 || k < 1) return 0;

        Arrays.sort(nums);
        int n = nums.length;
        int[] dp = new int[n];
        int maxLen = 1;

        for (int i = 1; i < n; i++) {
