            if (i >= zero) {
                dp[i] += dp[i - zero];
            }
            if (i >= one) {
                dp[i] += dp[i - one];
            }
            dp[i] %= MOD;
        }
        long ans = 0;
        for (int i = low; i <= high; i++) {
            ans += dp[i];
            ans %= MOD;
        }
        return (int) ans;
    }
}

