public class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        // Initialize the min heap and the stack
        PriorityQueue<Character> minHeap = new PriorityQueue<>();
        Stack<Character> stack = new Stack<>();

        for (char c : chars) {
            minHeap.offer(c);
        }

        StringBuilder sb = new StringBuilder();
        int i = n - 1;

        while (!minHeap.isEmpty() || !stack.isEmpty()) {

            // If the last character of t is smaller than or equal to the smallest character in s, 
            // then we can directly append it to t
            if (!stack.isEmpty() && (minHeap.isEmpty() || stack.peek() <= minHeap.peek())) {
                sb.append(stack.pop());
            } else {
                char c = minHeap.poll();
                stack.push(c);
            }
        }

        return sb.toString();
    }
}

