public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        boolean[] visited = new boolean[n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        long sum = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int weight = boxes[i][1];
                int port = boxes[i][0];
                pq.offer(new int[]{port, weight});
                sum += weight;
                while (!pq.isEmpty() && sum > maxWeight || pq.size() > maxBoxes) {
                    int[] top = pq.poll();
                    if (top[0] != port) {
                        visited[top[0]] = true;
                        sum -= top[1];
                    }
                }
            }
        }

        return pq.size() + 1;
    }
}

