import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                map.put(i * n + j, matrix[i][j]);
            }
        }

        List<int[]> list = new ArrayList<>(map.keySet());
        Collections.sort(list, (a, b) -> {
            int x = Math.abs(map.get(a));
            int y = Math.abs(map.get(b));
            if (x == y) return a - b;
            else return y - x;
        });

        Map<Integer, Integer> rankMap = new HashMap<>();
        for (int i = 0; i < list.size(); i++) {
            int key = list.get(i)[0];
            int value = map.get(key);
            if (!rankMap.containsKey(value)) {
                rankMap.put(value, i + 1);
            }
        }

        int[][] ans = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                ans[i][j] = rankMap.get(matrix[i][j]);
            }
        }
        return ans;
    }
}

