public class Solution {
    public int[] getSumAbsoluteDifferences(int[] nums) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            long sumRight = prefix[n] - prefix[i + 1];
            long sumLeft = prefix[i] - (i * nums[i]);
            result[i] = (int) ((sumRight - sumLeft) + Math.abs(nums[i] - sumLeft));
        }

        return result;
    }
}

