public class Solution {

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> set = new HashSet<>();
        for (int i : forbidden) {
            set.add(i);
        }

        Queue<Pair> queue = new LinkedList<>();
        boolean[][] visited = new boolean[100001][2];
        queue.offer(new Pair(0, false));
        visited[0][false] = true;

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair pair = queue.poll();

                if (pair.i == x) return steps;

                int forward = pair.i + a;
                int backward = pair.i - b;

                if (!set.contains(forward)) {
                    if (!visited[forward][true]) {
                        visited[forward][true] = true;
                        queue.offer(new Pair(forward, true));
                    }
                }

                if (pair.b) {
                    if (!set.contains(backward)) {
                        if (!visited[backward][false]) {
                            visited[backward][false] = true;
                            queue.offer(new Pair(backward, false));
                        }
                    }
                } else {
                    if (!set.contains(forward)) {
                        if (!visited[forward][true]) {
                            visited[forward][true] = true;
                            queue.offer(new Pair(forward, true));
                        }
                    }

                    int newBackward = pair.i - b;
                    if (!set.contains(newBackward) && !pair.b) {
                        if (!visited[newBackward][false]) {
                            visited[newBackward][false] = true;
                            queue.offer(new Pair(newBackward, false));
                        }
                    }
                }
            }

            steps++;
        }

        return -1;
    }
