public class Solution {
    public int[] bestCoordinate(int[][] towers, int radius) {
        Map<String, Integer> map = new HashMap<>();
        for (int[] tower : towers) {
            int x = tower[0];
            int y = tower[1];
            int q = tower[2];
            for (int i = -radius; i <= radius; i++) {
                for (int j = -radius; j <= radius; j++) {
                    if (Math.sqrt(i * i + j * j) <= radius) {
                        String key = x + "," + y;
                        int distance = Math.abs(x - i) + Math.abs(y - j);
                        map.put(key, Math.max(map.getOrDefault(key, 0), q / (1 + distance)));
                    }
                }
            }
        }

        int maxQuality = 0;
        String bestCoordinate = "";
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            if (entry.getValue() > maxQuality) {
                maxQuality = entry.getValue();
                bestCoordinate = entry.getKey();
            } else if (entry.getValue().equals(maxQuality)) {
                int[] current = getCoordinates(bestCoordinate);
                int[] newCoord = getCoordinates(entry.getKey());
                if ((newCoord[0] < current[0]) || (newCoord[0].equals(current[0]) && newCoord[1] < current[1])) {
                    bestCoordinate = entry.getKey();
                }
            }
        }

        return getCoordinates(bestCoordinate);
    }

    private int[] getCoordinates(String key) {
        String[] parts = key.split(",");
        return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
    }
}

