public class Solution {
    public int waysToMakeFair(int[] nums) {
        int oddSum = 0, evenSum = 0;
        for (int i = 0; i < nums.length; i++) {
            if ((i & 1) == 0) {
                evenSum += nums[i];
            } else {
                oddSum += nums[i];
            }
        }

        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            if ((i & 1) == 0) {
                if (evenSum - nums[i] + oddSum == oddSum) {
