        for (int i = 1; i < n; i++) {
            dp[i] += dp[i - 1];
        }

        int[][] prefMax = new int[n][n];
        for (int gap = 2; gap <= n; gap++) {
            for (int i = 0; i + gap - 1 < n; i++) {
                int j = i + gap - 1;
                prefMax[i][j] = Math.max(dp[j] - dp[i], prefMax[i + 1][j]);
