public class Solution {
    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            available.add(i);
        }
        int n = arrival.length;
        int[] count = new int[k];
        for (int i = 0; i < n; i++) {
            while (!pq.isEmpty() && pq.peek()[0] <= arrival[i]) {
                int[] temp = pq.poll();
                if (temp[1] > available.first()) {
                    continue;
                }
                count[temp[1]]++;
                available.remove(temp[1]);
                available.add(temp[1] + 1);
            }
            if (!available.isEmpty()) {
                int nextAvailable = available.ceiling(arrival[i] % k);
                if (nextAvailable == null) {
                    nextAvailable = available.first();
                }
                pq.offer(new int[]{arrival[i] + load[i], nextAvailable});
                available.remove(nextAvailable);
                available.add(nextAvailable + 1);
            }
        }
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (count[i] == Math.max(count)) {
                res.add(i);
            }
        }
        return res;
    }

    public static class Server {
        int id;
        int busyTime;

        public Server(int id, int busyTime) {
            this.id = id;
            this.busyTime = busyTime;
        }
    }
}

