import java.util.PriorityQueue;

public class Solution {
    public int stoneGameIII(int[] stones) {
        int n = stones.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + stones[i];
        }
        int aliceScore = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int i = n - 1; i >= 0; i--) {
            int score = prefixSum[n] - prefixSum[i + 1];
            if (i == n - 1) {
                aliceScore += score;
                pq.offer(score);
            } else {
                while (!pq.isEmpty() && pq.peek() <= score) {
                    aliceScore += pq.poll();
                }
                pq.offer(score);
            }
        }
        return aliceScore > prefixSum[n] / 2 ? 1 : -1;
    }
}

