import java.util.LinkedList;
public class Solution {
    public int minimumOneBitOperations(int n) {
        LinkedList<Integer> memo = new LinkedList<>();
        return helper(n, memo);
    }

    private int helper(int n, LinkedList<Integer> memo) {
        if (n == 0) return 0;
        if (memo.contains(n)) return memo.get(memo.indexOf(n));
        int result = n % 2 + helper(n >> 1, memo);
        memo.add(n, result);
        return result;
    }
}

