import java.util.*;

public class Solution {
    public boolean judgePoint24(int[] cards) {
        Arrays.sort(cards);
        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                for (int k = j + 1; k < 4; k++) {
                    for (int l = k + 1; l < 4; l++) {
                        if (dfs(cards[i], cards[j], cards[k], cards[l])) return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean dfs(double a, double b, double c, double d) {
        if (Math.abs(a + b + c + d - 24.0) < 1e-6) return true;

        for (int op : new int[]{1, 2, 3}) {
            switch (op) {
                case 1:
                    if (dfs(a + b, c, d, 0)) return true;
                    break;
                case 2:
                    if (b != 0 && dfs(a / b, c, d, 0)) return true;
                    if (c != 0 && dfs(a, c / d, d, 0)) return true;
                    if (d != 0 && dfs(a, c, d / a, 0)) return true;
                    break;
                case 3:
                    if (dfs(a * b, c, d, 0)) return true;
                    if (c != 0 && dfs(a, b, c / d, 0)) return true;
                    if (d != 0 && dfs(a, b, d / a, 0)) return true;
                    break;
            }
        }

        return false;
    }
}

