import java.util.*;

public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] pos : positions) {
            set.add(pos[0]);
            set.add(pos[0] + pos[1]);
        }
        int n = set.size();
        int[] arr = new int[n];
        int i = 0;
        for (Integer num : set) {
            arr[i++] = num;
        }

        List<Integer> ans = new ArrayList<>();
        int globalMax = 0;

        for (int[] pos : positions) {
            int x1 = Collections.binarySearch(arr, pos[0]);
            int x2 = Collections.binarySearch(arr, pos[0] + pos[1]);

            if (x1 < 0) x1 = -x1 - 1;
            if (x2 < 0) x2 = -x2 - 1;

            int currMax = globalMax;
            for (int j = x1; j <= x2; j++) {
                currMax = Math.max(currMax, arr[j] - pos[0]);
            }

            ans.add(currMax);
            globalMax = Math.max(globalMax, currMax);

        }
        return ans;
    }
}

