public class Solution {
    public int findLongestChain(int[][] pairs) {
        Arrays.sort(pairs, Comparator.comparingInt(a -> a[1]));

        int chain = 0;
        int prevEnd = Integer.MIN_VALUE;

        for (int[] pair : pairs) {
            if (pair[0] > prevEnd) {
                chain++;
                prevEnd = pair[1];
            }
        }

        return chain;
    }
}

