    private String traverse(TreeNode node) {
        if (node == null) {
            return "#";
        }
        String serial = node.val + "," + traverse(node.left) + "," + traverse(node.right);
        map.put(serial, node);
        if (map.get(serial).count > 1) {
            result.add(map.get(serial));
        }
        return serial;
    }

    private class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        int count;

        public TreeNode(int x) {
            val = x;
        }
    }
}

