import java.util.*;

public class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        Map<String, List<String>> map = new HashMap<>();

        for (String path : paths) {
            String[] components = path.split(" ");
            String directory = components[0];

            for (int i = 1; i < components.length; i++) {
                int index = components[i].indexOf('(');
                String filename = components[i].substring(0, index);
                String content = components[i].substring(index + 1, components[i].length() - 1);

                if (!map.containsKey(content)) {
                    map.put(content, new ArrayList<>());
                }
                map.get(content).add(directory + "/" + filename);
            }
        }

        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, List<String>> entry : map.entrySet()) {
            if (entry.getValue().size() > 1) {
                result.add(entry.getValue());
            }
        }

        return result;
    }
}

