public class Solution {
    public int findNumberOfLIS(int[] nums) {
        if (nums.length == 0) return 0;

        int n = nums.length;
        int[] length = new int[n];
        int[] count = new int[n];

        for (int i = 0; i < n; i++) {
            length[i] = 1;
            count[i] = 1;
        }

        int maxLength = 1;
        int maxCount = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    if (length[i] == length[j]) {
                        length[i]++;
                        count[i] += count[j];
                    } else if (length[i] == length[j] + 1) {
                        count[i] += count[j];
                    }
                }
            }

            if (length[i] > maxLength) {
                maxCount = count[i];
                maxLength = length[i];
            } else if (length[i] == maxLength) {
                maxCount += count[i];
            }
        }

        return maxCount;
    }
}

