public class Solution {
    public String solveEquation(String equation) {
        int x = 0, y = 0;
        boolean sign = true;
        StringBuilder num = new StringBuilder();

        for (int i = 0; i < equation.length(); i++) {
            char c = equation.charAt(i);

            if (c == '+' || c == '-') {
                if (!num.toString().isEmpty()) {
                    y += sign ? Integer.parseInt(num.toString()) : -Integer.parseInt(num.toString());
                    num.setLength(0);
                }

                sign = c == '+';
            } else if (Character.isDigit(c)) {
                num.append(c);
            } else if (c == 'x') {
                x += sign ? 1 : -1;
                sign = true;
            }
        }

        y += sign ? Integer.parseInt(num.toString()) : -Integer.parseInt(num.toString());

        int diff = x - y;

        if (diff == 0) return "Infinite solutions";
        else if (x % diff == 0 && y % diff == 0) return "No solution";
        else return "x=" + diff;
    }
}

