public class Solution {
    public int minSteps(int n) {
        int[] dp = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            int min = Integer.MAX_VALUE;
            for (int j = 1; j * j <= i; j++) {
                if (i % j == 0) {
                    min = Math.min(min, dp[i - j] + (j != i / j ? 2 : 1));
                }
            }
            dp[i] = min;
        }
        return dp[n];
    }
}

