import com_github_leetcode.TreeNode;

public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        long min = Long.MAX_VALUE;
        long secondMin = Long.MAX_VALUE;

        dfs(root, min, secondMin);

        if (secondMin == Long.MAX_VALUE)
            return -1;
        else
            return (int) secondMin;
    }

    private void dfs(TreeNode node, long min, long secondMin) {
        if (node != null) {
            if (node.val > min && node.val < secondMin)
                secondMin = node.val;
            else if (node.val <= min)
                min = node.val;

            dfs(node.left, min, secondMin);
            dfs(node.right, min, secondMin);
        }
    }
}

