public class Solution {
    public int[] constructArray(int n, int k) {
        int[] result = new int[n];
        int start = 1;
        int end = n;
        boolean isStartOdd = true;

        for (int i = 0; i < n - k; i++) {
            if (isStartOdd) {
                result[i] = start++;
            } else {
                result[i] = end--;
            }
            isStartOdd = !isStartOdd;
        }

