            maxHeap.offer(entry);
        }

        List<String> result = new ArrayList<>();

        while (!maxHeap.isEmpty() && k > 0) {
            result.add(maxHeap.poll().getKey());
            k--;
        }

        Collections.sort(result);

        return result;
    }
}

