import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            indexMap.put(inorder[i], i);
        }

        return buildTree(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1, indexMap);
    }

    private TreeNode buildTree(int[] preorder, int preStart, int preEnd, int[] inorder, int inStart, int inEnd, Map<Integer, Integer> indexMap) {
        if (preStart > preEnd || inStart > inEnd) return null;

        TreeNode root = new TreeNode(preorder[preStart]);
        int inRootIndex = indexMap.get(root.val);

        root.left = buildTree(preorder, preStart + 1, preStart + inRootIndex - inStart, inorder, inStart, inRootIndex - 1, indexMap);
        root.right = buildTree(preorder, preStart + inRootIndex - inStart + 1, preEnd, inorder, inRootIndex + 1, inEnd, indexMap);

        return root;
    }
}

