        if (index != 0) {
            root.left = buildTree(Arrays.copyOfRange(inorder, 0, index), 
                                  Arrays.copyOfRange(postorder, 0, postorder.length - 1 - (inorder.length - index)));
        }

        return root;
    }

    private int findIndex(int[] inorder, int target) {
        for (int i = 0; i < inorder.length; i++) {
            if (inorder[i] == target) return i;
        }
        return -1;
    }
