public class Solution {
    public void reorderList(ListNode head) {
        if (head == null || head.next == null || head.next.next == null) return;

        ListNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode secondHalfTail = slow;
        ListNode firstHalf = head;
        ListNode secondHalf = slow.next;
        secondHalfTail.next = null;

        ListNode prev = null;
        while (firstHalf != secondHalf) {
            ListNode nextNodeFirstHalf = firstHalf.next;
            ListNode nextNodeSecondHalf = secondHalf.next;

            firstHalf.next = secondHalf;
            secondHalf.next = nextNodeFirstHalf;

            prev = secondHalf;
            firstHalf = nextNodeFirstHalf;
            secondHalf = nextNodeSecondHalf;
        }

        if (firstHalf == secondHalf) {
            prev.next = null;
        }
    }
}

