        int[] counts = new int[n];
        for (int i = 0; i < n; i++) {
            if (i > 0 && text.charAt(i - 1) == text.charAt(i)) {
                counts[i] += counts[i - 1];
            }
            counts[i] += charCount.getOrDefault(text.charAt(i), 0);
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0 && text.charAt(i) == text.charAt(i - 1)) {
                maxLen = Math.max(maxLen, counts[i] - charCount.get(text.charAt(i)));
            } else {
                maxLen = Math.max(maxLen, counts[i]);
            }
        }

        for (int i = 0; i < n; i++) {
            if (i > 0 && text.charAt(i) == text.charAt(i - 1)) {
                int left = i - 2 >= 0 ? counts[i - 2] : 0;
                maxLen = Math.max(maxLen, counts[i] + charCount.get(text.charAt(i)) - left);
            }
        }

        return maxLen;
