public class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> set = new HashSet<>();
        for (int i : to_delete) {
            set.add(i);
        }
        List<TreeNode> res = new ArrayList<>();

        dfs(root, true, set, res);

        if (!set.contains(root.val)) {
            res.add(0, root);
        }

        return res;
    }

    private TreeNode dfs(TreeNode node, boolean isRoot, Set<Integer> set, List<TreeNode> res) {
        if (node == null) {
            return null;
        }
        if (set.contains(node.val)) {
            if (isRoot) {
                TreeNode left = dfs(node.left, false, set, res);
                TreeNode right = dfs(node.right, false, set, res);
                return null;
            } else {
                node.left = dfs(node.left, false, set, res);
                node.right = dfs(node.right, false, set, res);
                return node;
            }
        }

        if (isRoot) {
            TreeNode left = dfs(node.left, false, set, res);
            TreeNode right = dfs(node.right, false, set, res);
            if (left == null && right == null) {
                return null;
            } else if (left != null && right == null) {
                return left;
            } else if (left == null && right != null) {
                return right;
            } else {
                return node;
            }
        }

        return node;
    }
}

