        int n = s.length();
        int[] hash = new int[n + 1];
        for (int i = 0; i < n; i++) {
            hash[i + 1] = hash[i];
            if ((s.charAt(i) & 1) != 0) {
                hash[i + 1]++;
            }
        }

        List<Boolean> res = new ArrayList<>();
        for (int[] query : queries) {
            int left = query[0], right = query[1], k = query[2];
            int countOdd = hash[right + 1] - hash[left];
