public class Solution {
    public int longestDecomposition(String text) {
        int n = text.length();
        int[] dp = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = -1;
        }
        return dfs(text, 0, n - 1, dp);
    }

    private int dfs(String text, int start, int end, int[] dp) {
        if (start > end) {
            return 0;
        }
        if (dp[start] != -1) {
            return dp[start];
        }
        int ans = 0;
        for (int i = start; i <= end; i++) {
            if (text.substring(start, i + 1).equals(text.substring(end - (i - start) + 1, end + 1))) {
                ans = Math.max(ans, dfs(text, start, i, dp) + dfs(text, i + 1, end, dp));
            }
        }
        dp[start] = ans;
        return ans;
    }
}

