public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int n = obstacles.length;
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            while (!pq.isEmpty() && pq.peek()[0] > obstacles[i]) {
                int[] temp = pq.poll();
                pq.offer(new int[]{temp[0], temp[1] + 1});
            }

            if (pq.isEmpty()) {
                ans[i] = 1;
                pq.offer(new int[]{obstacles[i], 1});
            } else {
                ans[i] = pq.peek()[1] + 1;
                pq.offer(new int[]{obstacles[i], ans[i]});
            }
        }

        return ans;
    }
}

