import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int smallestChair(int[][] times, int targetFriend) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int[] freeChairs = new int[times.length];
        Arrays.fill(freeChairs, -1);
        int chairNum = 0;

        for (int i = 0; i < times.length; i++) {
            pq.offer(new int[]{times[i][0], i});
        }

        while (!pq.isEmpty()) {
            int[] currTime = pq.poll();

            if (currTime[1] == targetFriend) {
                return chairNum;
            } else if (freeChairs[currTime[1]] != -1) {
                continue;
            } else {
                freeChairs[currTime[1]] = chairNum;
                chairNum++;
            }

            int[] nextTime = pq.poll();
            if (nextTime == null || nextTime[0] > currTime[0]) {
                continue;
            }

            pq.offer(new int[]{nextTime[0], nextTime[1]});
        }

        return -1;
    }
}

