public class Solution {
    public boolean checkMove(char[][] board, int rMove, int cMove, char color) {
        // Check if the cell is already occupied by a different color
        if (board[rMove][cMove] != '.' && board[rMove][cMove] != color) {
            return false;
        }

        // Check horizontal lines
        for (int i = Math.max(0, cMove - 2); i <= Math.min(cMove + 2, 7); i++) {
            if (board[rMove][i] == '.' || board[rMove][i] != color) {
                continue;
            }
            int count = 1;
            for (int j = i + 1; j <= Math.min(i + 3, cMove + 2); j++) {
                if (board[rMove][j] == '.' || board[rMove][j] != color) {
                    break;
                }
                count++;
            }
            for (int j = i - 1; j >= Math.max(j - 3, cMove - 2); j--) {
                if (board[rMove][j] == '.' || board[rMove][j] != color) {
                    break;
                }
                count++;
            }
            if (count >= 3) {
                return true;
            }
        }

        // Check vertical lines
        for (int i = Math.max(0, rMove - 2); i <= Math.min(rMove + 2, 7); i++) {
            if (board[i][cMove] == '.' || board[i][cMove] != color) {
                continue;
            }
            int count = 1;
            for (int j = i + 1; j <= Math.min(i + 3, rMove + 2); j++) {
                if (board[j][cMove] == '.' || board[j][cMove] != color) {
                    break;
                }
                count++;
            }
            for (int j = i - 1; j >= Math.max(j - 3, rMove - 2); j--) {
                if (board[j][cMove] == '.' || board[j][cMove] != color) {
                    break;
                }
                count++;
            }
            if (count >= 3) {
                return true;
            }
        }

        // Check diagonal lines
        for (int i = Math.max(0, rMove - 2); i <= Math.min(rMove + 2, 7); i++) {
            for (int j = Math.max(0, cMove - 2); j <= Math.min(cMove + 2, 7); j++) {
                if ((i == rMove || j == cMove) && board[i][j] != color) {
                    continue;
                }
                int count = 1;
                for (int k = i + 1; k <= Math.min(i + 3, rMove + 2); k++) {
                    for (int l = j + 1; l <= Math.min(j + 3, cMove + 2); l++) {
                        if ((k == rMove || l == cMove) && board[k][l] != color) {
                            break;
                        }
                        count++;
                    }
                }
                for (int k = i - 1; k >= Math.max(k - 3, rMove - 2); k--) {
                    for (int l = j - 1; l >= Math.max(l - 3, cMove - 2); l--) {
                        if ((k == rMove || l == cMove) && board[k][l] != color) {
                            break;
                        }
                        count++;
                    }
                }
                if (count >= 3) {
                    return true;
                }
            }
        }

        // If no good line is found, return false
        return false;
    }
}

