public class Solution {
    public int countSpecialSubsequences(int[] nums) {
        long MOD = (long) 1e9 + 7;
        long[][] dp0 = new long[nums.length][3];
        long[][] dp1 = new long[nums.length][3];
        long[][] dp2 = new long[nums.length][3];

        for (int i = nums.length - 1; i >= 0; i--) {
            if (nums[i] == 0) {
                dp0[i][0] = 1;
                dp0[i][1] += dp1[i + 1][2];
                dp0[i][2] += dp2[i + 1][2];

                for (int j = 0; j < 3; j++) {
                    dp0[i][j] %= MOD;
                }
            } else if (nums[i] == 1) {
                dp1[i][0] = 1;
                dp1[i][1] += dp0[i + 1][2];
                dp1[i][2] += dp2[i + 1][2];

                for (int j = 0; j < 3; j++) {
                    dp1[i][j] %= MOD;
                }
            } else if (nums[i] == 2) {
                dp2[i][0] = 1;
                dp2[i][1] += dp0[i + 1][2];
                dp2[i][2] += dp1[i + 1][2];

                for (int j = 0; j < 3; j++) {
                    dp2[i][j] %= MOD;
                }
            }
        }

        return (int) ((dp0[0][2] + dp1[0][2] + dp2[0][2]) % MOD);
    }
}

