public class Solution {
    public int countSubIslands(int[][] grid1, int[][] grid2) {
        int m = grid1.length;
        int n = grid1[0].length;
        boolean[][] visited = new boolean[m][n];

        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid2[i][j] == 1 && !visited[i][j]) {
                    if (isSubIsland(grid1, grid2, visited, i, j)) {
                        count++;
                    }
                }
            }
        }

        return count;
    }

    private boolean isSubIsland(int[][] grid1, int[][] grid2, boolean[][] visited, int i, int j) {
        if (i < 0 || i >= grid1.length || j < 0 || j >= grid1[0].length) {
            return false;
        }

        if (grid2[i][j] == 0) {
            return true;
        }

        visited[i][j] = true;

        boolean isSubIsland = true;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            int x = i + dir[0];
            int y = j + dir[1];
            if (!visited[x][y] && grid2[x][y] == 1) {
                isSubIsland &= isSubIsland(grid1, grid2, visited, x, y);
            }
        }

        return isSubIsland;
    }
}

