import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] findFarmland(int[][] land) {
        int m = land.length, n = land[0].length;
        boolean[][] visited = new boolean[m][n];
        List<int[]> res = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && land[i][j] == 1) {
                    int[] group = dfs(land, visited, res, i, j);
                    if (group != null) {
                        res.add(group);
                    }
                }
            }
        }

        return res.toArray(new int[0][]);
    }

    private int[] dfs(int[][] land, boolean[][] visited, List<int[]> res, int i, int j) {
        int m = land.length, n = land[0].length;
        if (i < 0 || i >= m || j < 0 || j >= n || !land[i][j] == 1 || visited[i][j]) {
            return null;
        }

        visited[i][j] = true;

        int[] group = new int[4];
        int r1 = i, c1 = j, r2 = i, c2 = j;

        // DFS for right
        int[] temp = dfs(land, visited, res, i, j + 1);
        if (temp != null) {
            r2 = Math.max(r2, temp[0]);
            c2 = Math.max(c2, temp[3]);
        }

        // DFS for down
        temp = dfs(land, visited, res, i + 1, j);
        if (temp != null) {
            r2 = Math.max(r2, temp[0]);
            c2 = Math.max(c2, temp[3]);
        }

        group[0] = r1;
        group[1] = c1;
        group[2] = r2;
        group[3] = c2;

        return group;
    }
}

