public class Solution {
    public List<List<Long>> splitPainting(int[][] segments) {
        Arrays.sort(segments, (a, b) -> a[0] - b[0]);
        long[] prefixSum = new long[segments.length + 1];
        for (int i = 0; i < segments.length; i++) {
            prefixSum[i + 1] = prefixSum[i] + segments[i][2];
        }
        List<List<Long>> result = new ArrayList<>();
        int start = -1, end = -1;
        for (int i = 0; i <= segments.length; i++) {
            if (i == segments.length || segments[i][0] != segments[i - 1][0]) {
                if (start != -1) {
                    result.add(Arrays.asList(start, segments[start][1], prefixSum[i] - prefixSum[start]));
                }
                start = i;
                end = i;
            } else {
                end = i;
            }
        }
        return result;
    }
}

