        for (int i = 1; i < n; i++) {
            if ((i + 1) % 2 == 0 || nextVisit[i] > i) {
                dp[i] = dp[nextVisit[i]] + 1;
            } else {
                dp[i] = dp[(i + 1) % n] + 1;
            }
        }
        long ans = Long.MAX_VALUE;
        for (long val : dp) {
            ans = Math.min(ans, val);
        }
        return (int) ((ans - 1) % (1000000007));
    }
}

