import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public TreeNode canMerge(List<TreeNode> trees) {
        Map<Integer, Integer> rootCount = new HashMap<>();
        for (TreeNode tree : trees) {
            if (tree != null) {
                rootCount.put(tree.val, rootCount.getOrDefault(tree.val, 0) + 1);
            }
        }

        Queue<TreeNode> queue = new ArrayDeque<>(trees);
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node == null) continue;
            int count = rootCount.get(node.val);
            if (count > 1) {
                rootCount.put(node.val, count - 1);
                if (node.left != null && node.right != null) {
                    node.left = null;
                    node.right = null;
                } else if (node.left == null) {
                    queue.offer(node.right);
                    node.right = null;
                } else {
                    queue.offer(node.left);
                    node.left = null;
                }
            } else if (count == 1 && node.left != null && node.right != null) {
                TreeNode root = queue.poll();
                if (root.val < node.val) {
                    node.left = root;
                } else {
                    node.right = root;
                }
                rootCount.put(root.val, count - 1);
            }
        }

        for (int count : rootCount.values()) {
            if (count > 0) return null;
        }

        return queue.poll();
    }
}

