public class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        Integer[][] dp = new Integer[n + 1][n];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], null);
        }
        return dfs(0, tasks, sessionTime, dp);
    }

    private int dfs(int idx, int[] tasks, int sessionTime, Integer[][] dp) {
        if (idx == tasks.length) {
            return 1;
        }
        if (dp[idx][tasks.length - idx] != null) {
            return dp[idx][tasks.length - idx];
        }
        int ans = Integer.MAX_VALUE;
        for (int i = idx; i < tasks.length; i++) {
            if (tasks[i] <= sessionTime && (i == idx || tasks[i] + tasks[idx] > sessionTime)) {
                int res = dfs(i + 1, tasks, sessionTime, dp);
                ans = Math.min(ans, res + 1);
            }
        }
        return dp[idx][tasks.length - idx] = ans;
    }
}

