public class Solution {
    public int minSpaceWastedKResizing(int[] arr, int k) {
        int n = arr.length;
        long[][] dp = new long[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = Long.MAX_VALUE / 2;
            }
        }

        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            long minVal = Long.MAX_VALUE;
            for (int j = 1; j <= k; j++) {
                int prevSize = (int) Math.pow(2, i - 1);
                if (prevSize < arr[i - 1]) {
                    minVal = Math.min(minVal, dp[i - 1][j]);
                }
                long currWasted = (long) prevSize * j - arr[i - 1];
                dp[i][j] = Math.min(dp[i][j], currWasted + minVal);
            }
        }

        int ans = Long.MAX_VALUE;
        for (int i = 0; i <= k; i++) {
            ans = Math.min(ans, dp[n][i]);
        }

        return ans;
    }
}

