public class Solution {
    public long maxPoints(int[][] points) {
        int m = points.length;
        int n = points[0].length;
        long[] dp = new long[m];

        for (int i = 0; i < m; i++) {
            int maxDiff = -1;
            int prevMaxIndex = -1;

            for (int j = 0; j < n; j++) {
                if (i == 0) {
                    dp[j] = points[i][j];
                } else {
                    long currPoints = points[i][j] + Math.max(dp[prevMaxIndex], dp[maxDiff]);

                    if (maxDiff == -1 || Math.abs(j - prevMaxIndex) < Math.abs(j - maxDiff)) {
                        currPoints -= Math.abs(j - prevMaxIndex);
                        maxDiff = prevMaxIndex;
                    } else {
                        currPoints -= Math.abs(j - maxDiff);
                    }

                    dp[j] = Math.max(currPoints, dp[j]);
                }

                if (dp[j] > dp[prevMaxIndex]) {
                    prevMaxIndex = j;
                }
            }
        }

        long maxPoints = 0;
        for (int i = 0; i < n; i++) {
            maxPoints = Math.max(maxPoints, dp[i]);
        }

        return maxPoints;
    }
}

