import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Map<Integer, Integer> primeFactorsMap = new HashMap<>();
    private Set<Integer> primes = new HashSet<>();

    public int numGoodSubarrays(int[] nums) {
        if (nums == null || nums.length == 0) return 0;

        for (int i = 2; i <= Math.sqrt(nums[0]); i++) {
            while (nums[0] % i == 0) {
                primeFactorsMap.put(i, primeFactorsMap.getOrDefault(i, 0) + 1);
                nums[0] /= i;
            }
        }

        if (nums[0] > 1) primeFactorsMap.put(nums[0], primeFactorsMap.getOrDefault(nums[0], 0) + 1);

        for (int num : nums) {
            for (int i = 2; i <= Math.sqrt(num); i++) {
                while (num % i == 0) {
                    if (!primes.contains(i)) primes.add(i);
                    primeFactorsMap.put(i, primeFactorsMap.getOrDefault(i, 0) + 1);
                    num /= i;
                }
            }

            if (num > 1 && !primes.contains(num)) primes.add(num);

            if (primeFactorsMap.size() == primes.size()) {
                int count = 1;
                for (int prime : primes) {
                    count *= primeFactorsMap.get(prime);
                }
                return count % MOD;
            }

            primeFactorsMap.clear();
            primes.clear();
        }

        return 0;
    }
}

