public class Solution {
    public int latestDayToCross(int row, int col, int[][] cells) {
        boolean[][] visited = new boolean[row + 1][col + 1];
        for (int i = 0; i <= row; i++) {
            Arrays.fill(visited[i], false);
        }
        int maxDay = 0;
        for (int day = 0; day < cells.length; day++) {
            int r = cells[day][0];
            int c = cells[day][1];
            visited[r][c] = true;
            if (isConnected(visited, row, col)) {
                maxDay = Math.max(maxDay, day);
            }
        }
        return maxDay;
    }

    private boolean isConnected(boolean[][] visited, int row, int col) {
        Queue<int[]> queue = new LinkedList<>();
        for (int i = 1; i <= row; i++) {
            if (!visited[i][1]) {
                queue.offer(new int[]{i, 1});
                visited[i][1] = true;
            }
        }
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            if (c == col) return true;
            for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 1 && nr <= row && !visited[nr][nc]) {
                    queue.offer(new int[]{nr, nc});
                    visited[nr][nc] = true;
                }
            }
        }
        return false;
    }
}

