            for (int l = i + 1; l <= k; ++l) {
                if (num.charAt(l) != num.charAt(i)) {
                    flag = false;
                    break;
                }
            }
            if (!flag) {
                continue;
            }
            res += dfs(k + 1, Math.max(j, k + 1));
        }
        dp[i] = res % MOD;
        return dp[i];
    }
}

