import java.util.Arrays;
import java.util.BitSet;

public class Solution {
    public boolean gcdSort(int[] nums) {
        int n = nums.length;
        BitSet bitset = new BitSet(n + 1);
        for (int num : nums) {
            if (num <= n) {
                bitset.set(num, true);
            }
        }

        for (int i = 2; i <= n; i++) {
            if (!bitset.get(i)) continue;
            int p = i * 2;
            while (p <= n) {
                bitset.clear(p);
                p += i;
            }
        }

        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);

        for (int i = 2; i <= n; i++) {
            if (!bitset.get(i)) continue;
            int j = i * i;
            while (j <= n) {
                isPrime[j] = false;
                j += i;
            }
        }

        boolean[] visited = new boolean[n + 1];
        for (int num : nums) {
            if (num > n || !isPrime[num]) continue;

            int group = -1;
            while (num != 0 && !visited[num]) {
                visited[num] = true;
                if (group == -1) group = num;
                num /= getGCD(group, num);
            }
        }

        Arrays.sort(nums);
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] > nums[i + 1]) return false;
        }
        return true;
    }

    private int getGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

