public class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        boolean[][] isPalindrome = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            isPalindrome[i][i] = true;
            if (i + 1 < n && s.charAt(i) == s.charAt(i + 1)) {
                isPalindrome[i][i + 1] = true;
            }
        }

        for (int len = 3; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j) && isPalindrome[i + 1][j - 1]) {
                    isPalindrome[i][j] = true;
                }
            }
        }

        long maxProduct = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (isPalindrome[i][j]) {
                    int oddLength1 = j - i + 1;
                    if (oddLength1 % 2 == 1) {
                        for (int k = j + 1; k < n; k++) {
                            if (isPalindrome[k][n - 1] && (k - j) % 2 == 0) {
                                int oddLength2 = k - j;
                                maxProduct = Math.max(maxProduct, (long) oddLength1 * oddLength2);
                            }
                        }
                    } else {
                        for (int k = i + 1; k < j; k++) {
                            if (isPalindrome[k][j] && (k - i) % 2 == 0) {
                                int oddLength2 = k - i;
                                maxProduct = Math.max(maxProduct, (long) oddLength1 * oddLength2);
                            }
                        }
                    }
                }
            }
        }

        return maxProduct;
    }
}

