            if (curr[2] > maxTime) continue;

            for (int[] neighbor : graph.get(curr[0])) {
                int time = Math.min(maxTime, curr[2] + neighbor[1]);

                if (dp[neighbor[0]][time] > dp[curr[0]][curr[2]] + passingFees[neighbor[0]]) {
                    dp[neighbor[0]][time] = dp[curr[0]][curr[2]] + passingFees[neighbor[0]];
                    pq.offer(new int[]{neighbor[0], dp[neighbor[0]][time], time});
                }
            }
        }

        int minCost = Integer.MAX_VALUE;

        for (int i = 0; i <= maxTime; i++) {
            minCost = Math.min(minCost, dp[n - 1][i]);
        }

        return minCost == Integer.MAX_VALUE ? -1 : minCost;
    }
}

