import java.util.*;

public class Solution {
    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 1; i < n; i++) {
            graph[parents[i]].add(i);
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = -1;
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);

        dfs(0, graph, parents, parent);

        for (int i = 0; i < queries.length; i++) {
            int node = queries[i][0], val = queries[i][1];
            ans[i] = findMaxXor(node, val, parent);
        }

        return ans;
    }

    private void dfs(int node, List<Integer>[] graph, int[] parents, int[] parent) {
        for (int child : graph[node]) {
            parent[child] = node;
            dfs(child, graph, parents, parent);
        }
    }

    private int findMaxXor(int node, int val, int[] parent) {
        if (node == -1) return 0;

        int maxXor = 0;
        while (val > 0 || maxXor > 0) {
            if ((maxXor & val) != 0) {
                maxXor ^= val;
                break;
            }
            int p = parent[node];
            node = p;
            if (node == -1) return maxXor;
        }

        int leftMaxXor = findMaxXor(parent[node], val, parent);
        return Math.max(maxXor, leftMaxXor);
    }
}

