public class Solution {
    public boolean sumGame(String num) {
        int n = num.length();
        int[] a = new int[n / 2];
        int[] b = new int[n - n / 2];

        for (int i = 0; i < n / 2; i++) {
            if (num.charAt(i * 2) != '?') {
                a[i] = num.charAt(i * 2) - '0';
            }
        }

        for (int i = 0; i < n - n / 2; i++) {
            if (num.charAt(n / 2 + i * 2) != '?') {
                b[i] = num.charAt(n / 2 + i * 2) - '0';
            }
        }

        int sumA = 0;
        for (int x : a) {
            sumA += x;
        }

        int sumB = 0;
        for (int x : b) {
            sumB += x;
        }

        if (sumA == sumB) return true;

        int diff = Math.abs(sumA - sumB);

        for (int i = 0; i < n / 2; i++) {
            if (num.charAt(i * 2) == '?') {
                a[i] += 9;
                sumA += 9;
                break;
            }
        }

        for (int i = 0; i < n - n / 2; i++) {
            if (num.charAt(n / 2 + i * 2) == '?') {
                b[i] += 9;
                sumB += 9;
                break;
            }
        }

        return Math.abs(sumA - sumB) != diff;
    }
}

