public class Solution {
    public int arrayNesting(int[] nums) {
        boolean[] visited = new boolean[nums.length];
        int maxLen = 0;

        for (int i = 0; i < nums.length; i++) {
            if (!visited[i]) {
                Set<Integer> set = new HashSet<>();
                int len = dfs(nums, i, visited, set);
                maxLen = Math.max(maxLen, len);
            }
        }

        return maxLen;
    }

    private int dfs(int[] nums, int index, boolean[] visited, Set<Integer> set) {
        if (set.contains(index)) {
            return 0;
        }

        set.add(index);
        visited[index] = true;
        return 1 + dfs(nums, nums[index], visited, set);
    }
}

