public class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][] memo = new int[n][n];
        return dfs(0, 0, 0, boxes, memo);
    }

    private int dfs(int l, int r, int count, int[] boxes, int[][] memo) {
        if (l > r) return 0;
        if (memo[l][r] != 0) return memo[l][r];
        while (r >= l && boxes[r] == boxes[r - 1]) {
            r--;
            count++;
        }
        int res = (count + 1) * (count + 1) + dfs(l, r - 1, 0, boxes, memo);
        for (int i = l; i <= r; i++) {
            if (boxes[i] == boxes[l]) {
                res = Math.max(res, dfs(i + 1, r, count + 1, boxes, memo) + (count + 1) * (count + 1));
            }
        }
        return memo[l][r] = res;
    }
}

