public class Solution {
    public boolean checkInclusion(String s1, String s2) {
        int lenS1 = s1.length();
        int lenS2 = s2.length();

        if (lenS1 > lenS2) return false;

        int[] hashS1 = new int[26];
        for (int i = 0; i < lenS1; i++) {
            hashS1[s1.charAt(i) - 'a']++;
        }

        int left = 0, right = 0;
        int[] hashWindow = new int[26];

        while (right < lenS2) {
            hashWindow[s2.charAt(right) - 'a']++;

            if (right - left + 1 == lenS1) {
                if (isMatch(hashS1, hashWindow)) return true;

                hashWindow[s2.charAt(left) - 'a']--;
                left++;
            }

            right++;
        }

        return false;
    }

    private boolean isMatch(int[] hashS1, int[] hashWindow) {
        for (int i = 0; i < 26; i++) {
            if (hashS1[i] != hashWindow[i]) return false;
        }
        return true;
    }
}

