public class Solution {
    public int longestPalindromeSubseq(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        for (int cl = 2; cl <= n; cl++) {
            for (int st = 0; st < n - cl + 1; st++) {
                int end = st + cl - 1;

                if (s.charAt(st) == s.charAt(end)) {
                    dp[st][end] = 2 + (dp[st + 1][end - 1] == 0 ? 0 : dp[st + 1][end - 1]);
                } else {
                    dp[st][end] = Math.max(dp[st + 1][end], dp[st][end - 1]);
                }
            }
        }

        return dp[0][n - 1];
    }
}

