public class Solution {
    public int nextGreaterElement(int n) {
        String str = Integer.toString(n);
        char[] arr = str.toCharArray();

        // Find k
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] < arr[i + 1]) {
                int k = i;
                break;
            }
        }

        if (k == 0) return -1;

        // Find l
        for (int j = arr.length - 1; j > k; j--) {
            if (arr[j] > arr[k]) {
                int l = j;
                break;
            }
        }

        // Swap k and l
        char temp = arr[l];
        arr[l] = arr[k];
        arr[k] = temp;

        // Reverse the part after k
        StringBuilder sb = new StringBuilder();
        for (int i = arr.length - 1; i >= k + 1; i--) {
            sb.append(arr[i]);
        }
        String str2 = sb.toString();

        // Build result
        char[] arr2 = new char[arr.length];
        System.arraycopy(arr, 0, arr2, 0, k + 1);
        for (int i = 0; i < str2.length(); i++) {
            arr2[k + 1 + i] = str2.charAt(i);
        }

        // Handle the case if ret > Integer.MAX_VALUE
        String result = new String(arr2);
        long ret = Long.parseLong(result);
        return (int) (ret <= Integer.MAX_VALUE ? ret : -1);
    }
}

