import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String fractionAddition(String expression) {
        int n = expression.length();
        List<Integer> numerators = new ArrayList<>();
        List<Integer> denominators = new ArrayList<>();

        int i = 0;
        while (i < n) {
            if (!Character.isDigit(expression.charAt(i))) {
                int j = i + 1;
                while (j < n && !Character.isDigit(expression.charAt(j))) {
                    j++;
                }
                String numeratorStr = expression.substring(i, j);
                i = j;

                j = i;
                while (j < n && Character.isDigit(expression.charAt(j))) {
                    j++;
                }
                String denominatorStr = expression.substring(i, j);
                i = j;

                numerators.add(Integer.parseInt(numeratorStr));
                denominators.add(Integer.parseInt(denominatorStr));
            } else {
                int j = i;
                while (j < n && Character.isDigit(expression.charAt(j))) {
                    j++;
                }
                String numeratorStr = expression.substring(i, j);
                i = j;

                numerators.add(Integer.parseInt(numeratorStr));
                denominators.add(1);
            }
        }

        long resultNumerator = 0;
        long resultDenominator = 1;
        for (int k = 0; k < numerators.size(); k++) {
            int numerator = numerators.get(k);
            int denominator = denominators.get(k);

            if ((resultNumerator * denominator) % (long) resultDenominator == 0) {
                resultNumerator *= denominator;
                resultDenominator *= denominator;
            } else {
                long gcd = gcd(resultNumerator * denominator, resultDenominator);
                resultNumerator = (resultNumerator * denominator) / gcd;
                resultDenominator /= gcd;
            }

            if ((numerator < 0 && resultNumerator >= 0) || (numerator > 0 && resultNumerator <= 0)) {
                resultNumerator *= -1;
            }
        }

        return resultNumerator + "/" + resultDenominator;
    }

    private long gcd(long a, long b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }
}

