public class Solution {
    private int sum = 0;

    public TreeNode convertBST(TreeNode root) {
        if (root == null) return null;

        // Traverse the right subtree first to get the sum of all keys greater than the current key
        convertBST(root.right);

        // Update the value of the current node by adding the sum to its original value
        root.val += sum;

        // Add the value of the current node to the sum for future nodes
        sum += root.val;

        // Traverse the left subtree
        convertBST(root.left);

        return root;
    }
}

