public class Solution {
    public int[] findFrequentTreeSum(TreeNode root) {
        Map<Integer, Integer> sumCount = new HashMap<>();
        dfs(root, sumCount);
        int maxCount = Collections.max(sumCount.values());
        List<Integer> result = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : sumCount.entrySet()) {
            if (entry.getValue() == maxCount) {
                result.add(entry.getKey());
            }
        }
        return Arrays.stream(result.toArray(new Integer[0])).mapToInt(Integer::intValue).toArray();
    }

    private int dfs(TreeNode node, Map<Integer, Integer> sumCount) {
        if (node == null) {
            return 0;
        }
        int sum = node.val + dfs(node.left, sumCount) + dfs(node.right, sumCount);
        sumCount.put(sum, sumCount.getOrDefault(sum, 0) + 1);
        return sum;
    }
}

