public class Solution {
    public int[] nextGreaterElements(int[] nums) {
        Deque<Integer> stack = new ArrayDeque<>();
        int n = nums.length;
        int[] result = new int[n];
        for (int i = 0; i < 2 * n; i++) {
            while (!stack.isEmpty() && nums[i % n] > nums[stack.peek()]) {
                result[stack.pop()] = nums[i % n];
            }
            stack.push(i % n);
        }
        for (int i = 0; i < n; i++) {
            if (result[i] == 0) {
                result[i] = -1;
            }
        }
        return result;
    }
}

