public class Solution {
    public int findPairs(int[] nums, int k) {
        Set<Integer> numSet = new HashSet<>();
        for (int num : nums) {
            numSet.add(num);
        }

        int count = 0;
        if (k == 0) {
            for (int num : numSet) {
                if (numSet.contains(num + k)) {
                    count++;
                }
            }
        } else {
            for (int num : numSet) {
