public class Solution {
    public int findMinMoves(int[] machines) {
        int n = machines.length;
        int sum = 0, max = 0;
        for (int i : machines) sum += i;
        if (sum % n != 0) return -1;
        int avg = sum / n;
        int[] diff = new int[n];
        for (int i = 0; i < n; i++) {
            diff[i] = machines[i] - avg;
            max = Math.max(max, Math.abs(diff[i]));
        }
        int res = max;
        for (int i : diff) res = Math.max(res, i);
        return res;
    }
}

