import java.util.*;

public class Solution {
    public char[][] updateBoard(char[][] board, int[] click) {
        int m = board.length;
        int n = board[0].length;
        int r = click[0];
        int c = click[1];

        if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] == 'X' || board[r][c] == 'B') {
            return board;
        }

        if (board[r][c] == 'M') {
            board[r][c] = 'X';
            return board;
        }

        int count = 0;
        for (int i = Math.max(0, r - 1); i <= Math.min(m - 1, r + 1); i++) {
            for (int j = Math.max(0, c - 1); j <= Math.min(n - 1, c + 1); j++) {
                if (board[i][j] == 'M') {
                    count++;
                }
            }
        }

        if (count > 0) {
            board[r][c] = (char) ('0' + count);
            return board;
        } else {
            board[r][c] = 'B';
            for (int i = Math.max(0, r - 1); i <= Math.min(m - 1, r + 1); i++) {
                for (int j = Math.max(0, c - 1); j <= Math.min(n - 1, c + 1); j++) {
                    if (i != r || j != c) {
                        updateBoard(board, new int[]{i, j});
                    }
                }
            }
        }

        return board;
    }
}

