public class Solution {
    private int nRows, nCols;
    private boolean[][] matrix;
    private Random random;
    private Set<Integer> rowSet;

    public Solution(int nRows, int nCols) {
        this.nRows = nRows;
        this.nCols = nCols;
        this.matrix = new boolean[nRows][nCols];
        this.random = new Random();
        this.rowSet = new HashSet<>();
    }

    public int[] flip() {
        if (rowSet.isEmpty()) {
            for (int i = 0; i < nRows; i++) {
                rowSet.add(i);
            }
        }

        int row = random.nextInt(rowSet.size());
        int col;
        do {
            col = random.nextInt(nCols);
        } while (!matrix[row][col]);

        matrix[row][col] = true;

        int[] result = new int[2];
        result[0] = row;
        result[1] = col;

        return result;
    }

    public void reset() {
        for (int i = 0; i < nRows; i++) {
            for (int j = 0; j < nCols; j++) {
                matrix[i][j] = false;
            }
        }
        rowSet.clear();
    }
}

