public class Solution {
    public int findMinDifference(List<String> timePoints) {
        Arrays.sort(timePoints);

        int minDiff = Integer.MAX_VALUE;
        for (int i = 0; i < timePoints.size() - 1; i++) {
            String[] time1 = timePoints.get(i).split(":");
            String[] time2 = timePoints.get(i + 1).split(":");

            int diff = Math.abs(Integer.parseInt(time1[0]) * 60 + Integer.parseInt(time1[1])
                    - (Integer.parseInt(time2[0]) * 60 + Integer.parseInt(time2[1])));

            minDiff = Math.min(minDiff, diff);
        }

        // consider the case where the smallest time is after the largest time
        String[] time1 = timePoints.get(0).split(":");
        String[] time2 = timePoints.get(timePoints.size() - 1).split(":");

        int diff = Math.abs(Integer.parseInt(time1[0]) * 60 + Integer.parseInt(time1[1])
                - (Integer.parseInt(time2[0]) * 60 + Integer.parseInt(time2[1])) + 24 * 60);

        minDiff = Math.min(minDiff, diff);

        return minDiff;
    }
}

