// Definition for a QuadTree node.
public class Solution {
    public boolean val;
    public boolean isLeaf;
    public Node topLeft;
    public Node topRight;
    public Node bottomLeft;
    public Node bottomRight;
}

public class Solution {
    public Node intersect(Node n1, Node n2) {
        if (n1 == null || n2 == null) return new Node();

        if (n1.isLeaf && n2.isLeaf && n1.val == n2.val) {
            return new Node(n1.val, true);
        }

        boolean topLeft = n1.isLeaf ? n1.val : intersect(n1.topLeft, n2.topLeft).val;
        boolean topRight = n1.isLeaf ? n1.val : intersect(n1.topRight, n2.topRight).val;
        boolean bottomLeft = n1.isLeaf ? n1.val : intersect(n1.bottomLeft, n2.bottomLeft).val;
        boolean bottomRight = n1.isLeaf ? n1.val : intersect(n1.bottomRight, n2.bottomRight).val;

        if (topLeft && topRight && bottomLeft && bottomRight) {
            return new Node(true, false, new Node(topLeft, true), new Node(topRight, true),
                    new Node(bottomLeft, true), new Node(bottomRight, true));
        } else if (!topLeft && !topRight && !bottomLeft && !bottomRight) {
            return new Node(false, false, new Node(topLeft, true), new Node(topRight, true),
                    new Node(bottomLeft, true), new Node(bottomRight, true));
        } else {
            return new Node(true, false,
                    topLeft ? intersect(n1.topLeft, n2.topLeft) : null,
                    topRight ? intersect(n1.topRight, n2.topRight) : null,
                    bottomLeft ? intersect(n1.bottomLeft, n2.bottomLeft) : null,
                    bottomRight ? intersect(n1.bottomRight, n2.bottomRight) : null);
        }
    }
}

