public class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        boolean[] visited = new boolean[n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0});
        visited[0] = true;
        int steps = 0;

        for (char c : key.toCharArray()) {
            int size = queue.size();

            while (!queue.isEmpty() && !visited[ring.indexOf(c)]) {
                int[] curr = queue.poll();
                int x = curr[0], y = curr[1];

                if (x > 0) {
                    int newX = x - 1;
                    if (!visited[newX]) {
                        visited[newX] = true;
                        queue.offer(new int[]{newX, y});
                    }
                }

                if (y > 0 && ring.charAt(x) != ring.charAt(y - 1)) {
                    int newY = y - 1;
                    if (!visited[n * newY + x]) {
                        visited[n * newY + x] = true;
                        queue.offer(new int[]{n * newY + x, newY});
                    }
                }

                if (x < n - 1) {
                    int newX = x + 1;
                    if (!visited[newX]) {
                        visited[newX] = true;
                        queue.offer(new int[]{newX, y});
                    }
                }

                if (y < n - 1 && ring.charAt(x) != ring.charAt(y + 1)) {
                    int newY = y + 1;
                    if (!visited[n * newY + x]) {
                        visited[n * newY + x] = true;
                        queue.offer(new int[]{n * newY + x, newY});
                    }
                }

                if (x > 0 && ring.charAt(y) == ring.charAt(x - 1)) {
                    int newX = x - 1;
                    if (!visited[newX]) {
                        visited[newX] = true;
                        queue.offer(new int[]{newX, y});
                    }
                }

                if (y > 0 && ring.charAt(x) == ring.charAt(y - 1)) {
                    int newY = y - 1;
                    if (!visited[n * newY + x]) {
                        visited[n * newY + x] = true;
                        queue.offer(new int[]{n * newY + x, newY});
                    }
                }

                if (x < n - 1 && ring.charAt(y) == ring.charAt(x + 1)) {
                    int newX = x + 1;
                    if (!visited[newX]) {
                        visited[newX] = true;
                        queue.offer(new int[]{newX, y});
                    }
                }

                if (y < n - 1 && ring.charAt(x) == ring.charAt(y + 1)) {
                    int newY = y + 1;
                    if (!visited[n * newY + x]) {
                        visited[n * newY + x] = true;
                        queue.offer(new int[]{n * newY + x, newY});
                    }
                }

                if (x > 0 && ring.charAt(x - 1) == c) {
                    steps += Math.min(Math.abs(x), n - x);
                    break;
                } else if (y > 0 && ring.charAt(y - 1) == c) {
                    steps += Math.min(Math.abs(y), n - y);
                    break;
                }
            }

            if (!visited[ring.indexOf(c)]) {
                return -1;
            }
        }

        return steps + key.length();
    }
}

