public class Solution {
    public String nearestPalindromic(String n) {
        long num = Long.parseLong(n);
        long[] res = new long[3];
        int idx = 0;

        for (long i = num - 1; i >= 10000000000000L; i--) {
            if (isPalindrome(i)) {
                res[idx++] = i;
                break;
            }
        }

        for (long i = num + 1; i <= 10000000000000L; i++) {
            if (isPalindrome(i)) {
                res[idx++] = i;
                break;
            }
        }

        long[] arr = new long[10];
        int j = 0;

        for (int k = n.length() - 1; k >= 0; k--) {
            arr[j] = n.charAt(k) - '0';
            j++;
        }

        if (arr[0] != 0 && arr[0] % 2 == 0) {
            long temp = 10 * arr[0];
            for (int k = 1; k < arr.length / 2; k++) {
                temp += 10 * arr[k];
                temp += 10 * arr[k];
            }
            res[idx++] = temp;
        }

        if (arr[0] % 2 == 1) {
            long temp = 10 * ((int) (arr[0] - 1));
            for (int k = 1; k < arr.length / 2; k++) {
                temp += 10 * arr[k];
                temp += 10 * arr[k];
            }
            res[idx++] = temp;
        }

        if (idx == 0) {
            return "99999999999";
        } else {
            long minDiff = Long.MAX_VALUE;
            int ansIdx = -1;

            for (int k = 0; k < idx; k++) {
                long diff = Math.abs(num - res[k]);
                if (diff < minDiff) {
                    minDiff = diff;
                    ansIdx = k;
                }
            }

            return String.valueOf(res[ansIdx]);
        }
    }

    public boolean isPalindrome(long num) {
        long temp = num;
        long rev = 0;

        while (temp != 0) {
            int rem = (int) (temp % 10);
            rev = rev * 10 + rem;
            temp /= 10;
        }

        return rev == num;
    }
}

