public class Solution {
    public String complexNumberMultiply(String num1, String num2) {
        int real1 = 0;
        int imag1 = 0;
        int real2 = 0;
        int imag2 = 0;

        for (int i = 0; i < num1.length(); i++) {
            if (num1.charAt(i) == '+') break;
            else if (Character.isDigit(num1.charAt(i))) {
                real1 = real1 * 10 + (num1.charAt(i) - '0');
            }
        }

        for (int i = 0; i < num2.length(); i++) {
            if (num2.charAt(i) == '+') break;
            else if (Character.isDigit(num2.charAt(i))) {
                real2 = real2 * 10 + (num2.charAt(i) - '0');
            }
        }

        for (int i = 0; i < num1.length(); i++) {
            if (num1.charAt(i) == 'i') break;
            else if (Character.isDigit(num1.charAt(i))) {
                imag1 = imag1 * 10 + (num1.charAt(i) - '0');
            }
        }

        for (int i = 0; i < num2.length(); i++) {
            if (num2.charAt(i) == 'i') break;
            else if (Character.isDigit(num2.charAt(i))) {
                imag2 = imag2 * 10 + (num2.charAt(i) - '0');
            }
        }

        int real = real1 * real2 - imag1 * imag2;
        int imag = real1 * imag2 + real2 * imag1;

        if (imag < 0) {
            return real + "+" + (-imag) + "i";
        } else {
            return real + "+" + imag + "i";
        }
    }
}

