        for (int i = 0; i < arr.length; i++) {
            if (!visited[i]) {
                dfs(arr, i, visited);
                count++;
            }
        }

        return count;
    }

    private void dfs(int[][] arr, int node, boolean[] visited) {
        visited[node] = true;

        for (int i = 0; i < arr.length; i++) {
            if (arr[node][i] == 1 && !visited[i]) {
                dfs(arr, i, visited);
            }
        }
    }
}

