public class Solution {
    public int findLUSlength(String[] strs) {
        for (String s : strs) {
            boolean isSubsequence = false;
            for (String t : strs) {
                if (!s.equals(t)) {
                    if (isSubsequenceOf(s, t)) {
                        isSubsequence = true;
                        break;
                    }
                } else {
                    continue;
                }
            }
            if (!isSubsequence) {
                return s.length();
            }
        }
        return -1;
    }

    private boolean isSubsequenceOf(String s, String t) {
        int i = 0, j = 0;
        while (i < s.length() && j < t.length()) {
            if (s.charAt(i) == t.charAt(j)) {
                i++;
            }
            j++;
        }
        return i == s.length();
    }
}

