import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        for (int i = 0; i < profits.length; i++) {
            pq.offer(new int[]{capital[i], profits[i]});
        }

        PriorityQueue<Integer> availableProjects = new PriorityQueue<>((a, b) -> b - a);

        while (!pq.isEmpty() && k > 0) {
            int[] project = pq.poll();

            if (project[0] <= w) {
                availableProjects.offer(project[1]);

                if (availableProjects.size() == k) {
                    break;
                }
            } else {
                pq.offer(project);
            }
        }

        while (!availableProjects.isEmpty()) {
            w += availableProjects.poll();
        }

        return w;
    }
}

