import java.util.Arrays;

public class Solution {
    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        long MOD = (long) 1e9 + 7;
        long[][][] dp = new long[m][n][maxMove + 1];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i][startColumn], -1);
        }
        return (int) dfs(m, n, maxMove, startRow, startColumn, dp, MOD);
    }

    private long dfs(int m, int n, int moveLeft, int row, int col, long[][][] dp, long MOD) {
        if (row < 0 || row >= m || col < 0 || col >= n) return 1;
        if (moveLeft == 0) return 0;
        if (dp[row][col][(int) moveLeft] != -1) return dp[row][col][(int) moveLeft];
        long ways = dfs(m, n, moveLeft - 1, row + 1, col, dp, MOD)
                + dfs(m, n, moveLeft - 1, row - 1, col, dp, MOD)
                + dfs(m, n, moveLeft - 1, row, col + 1, dp, MOD)
                + dfs(m, n, moveLeft - 1, row, col - 1, dp, MOD);
        return dp[row][col][(int) moveLeft] = ways % MOD;
    }
}

