public class Solution {
    public int checkRecord(int n) {
        long[] dp = new long[3];
        long[] ndp = new long[3];

        for (int i = 0; i < n; i++) {
            Arrays.fill(ndp, 0);
            ndp[0] += dp[0] + dp[1] + dp[2]; // A
            ndp[1] += dp[0] + Math.max(0, dp[1] - 1) + Math.max(0, dp[2] - 2); // L
            ndp[2] += dp[0]; // P

            long[] temp = dp;
            dp = ndp;
            ndp = temp;
        }

        return (int) ((dp[0] + dp[1] + dp[2]) % (1000000007));
    }
}

