import java.util.*;

public class Solution {
    public int numOfWays(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        return dfs(countMap, nums.length);
    }

    private int dfs(Map<Integer, Integer> countMap, int n) {
        if (countMap.size() == 1) {
            return 1;
        }

        List<Integer> keys = new ArrayList<>(countMap.keySet());
        Collections.sort(keys);

        int root = keys.get(0);
        int leftCount = countMap.get(root);
        int rightCount = n - leftCount - 1;

        if (leftCount > 1) {
            countMap.put(root, leftCount - 1);
        }

        if (rightCount > 0) {
            countMap.put(keys.get(1), rightCount);
        }

        long ways = dfs(countMap, n - 1);

        if (countMap.containsKey(root)) {
            int leftWays = 1;
            for (int i = 2; i < keys.size(); i++) {
                if (countMap.containsKey(keys.get(i))) {
                    leftWays *= factorial(countMap.get(keys.get(i)));
                }
            }

            ways = (ways * leftWays) % 1000000007;
        }

        return (int) ways;
    }

    private long factorial(int n) {
        if (n == 0 || n == 1) {
            return 1;
        } else {
            return (long) n * factorial(n - 1) % 1000000007;
        }
    }
}

