public class Solution {
    public int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
        Map<Integer, Integer> preferenceMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            preferenceMap.put(i, i);
        }

        for (int[] pair : pairs) {
            int x = pair[0], y = pair[1];
            preferenceMap.put(x, preferences[x][y]);
            preferenceMap.put(y, preferences[y][x]);
        }

        Map<Integer, Integer> unhappyFriends = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int x = pairs[i][0], y = pairs[i][1];
            boolean isUnhappy = false;
            for (int j = 0; j < preferences[x].length && !isUnhappy; j++) {
                if (preferences[x][j] == y) {
                    for (int k = 0; k < n; k++) {
                        int u = pairs[k][0], v = pairs[k][1];
                        if (u != x && v != x && preferenceMap.get(u) < preferenceMap.get(y)
                                && preferenceMap.get(x) < preferenceMap.get(v)) {
                            isUnhappy = true;
                            break;
                        }
                    }
                }
            }
            if (isUnhappy) {
                unhappyFriends.put(i, 1);
            }
        }

        return unhappyFriends.size();
    }
}

