public class Solution {
    public int maxDistance(int[] position, int m) {
        Arrays.sort(position);
        long left = 0, right = (long) 1e9 + 7;
        while (left < right) {
            long mid = left + (right - left) / 2;
            if (check(mid, position, m)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return (int) left;
    }

    private boolean check(long k, int[] position, int m) {
        long cnt = 1, prev = position[0];
        for (int i = 1; i < position.length; i++) {
            if (position[i] - prev >= k) {
                cnt++;
                prev = position[i];
            }
        }
        return cnt >= m;
    }
}

