import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minSubarray(int[] nums, int p) {
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }

        if (sum % p == 0) {
            return 0;
        }

        Map<Integer, Integer> prefixSumMap = new HashMap<>();
        int windowStart = 0;
        int minWindowSize = Integer.MAX_VALUE;

        long currentWindowSum = 0;
        for (int i = 0; i < nums.length; i++) {
            currentWindowSum += nums[i];

            if ((currentWindowSum % p) == (sum % p)) {
                minWindowSize = Math.min(minWindowSize, i - windowStart + 1);
            }

            int remainder = (int) ((currentWindowSum % p + p) % p);
            if (!prefixSumMap.containsKey(remainder)) {
                prefixSumMap.put(remainder, i);
            } else {
                minWindowSize = Math.min(minWindowSize, i - prefixSumMap.get(remainder));
            }
        }

        return minWindowSize == Integer.MAX_VALUE ? -1 : minWindowSize;
    }
}

