public class Solution {
    public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
        int maxProfit = 0;
        int maxRotations = 0;
        int currentProfit = 0;
        int rotations = 0;
        int waitingCustomers = 0;

        for (int i = 0; i < customers.length; i++) {
            waitingCustomers += customers[i];

            while (waitingCustomers >= 4) {
                int boarding = Math.min(4, waitingCustomers);
                currentProfit += boarding * boardingCost - runningCost;
                maxProfit = Math.max(maxProfit, currentProfit);

                if (currentProfit > maxProfit) {
                    maxRotations = rotations + 1;
                }

                waitingCustomers -= boarding;
            }

            if (waitingCustomers > 0) {
                int boarding = Math.min(waitingCustomers, 4);
                currentProfit += boarding * boardingCost - runningCost;

                if (currentProfit > maxProfit) {
                    maxRotations = rotations + 1;
                }
                waitingCustomers -= boarding;
            }

            rotations++;
        }

        return maxRotations == 0 ? -1 : maxRotations;
    }
}

