import java.util.*;

public class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int size1 = cost.size();
        int size2 = cost.get(0).size();

        boolean[] visited = new boolean[size1];
        int[][] dp = new int[1 << size2][size1];

        for (int i = 0; i < size1; i++) {
            Arrays.fill(dp[0 ^ (1 << i)][i], Integer.MAX_VALUE / 2);
            dp[0 ^ (1 << i)][i][0] = cost.get(i).get(0);
        }

        for (int mask = 1; mask < (1 << size2); mask++) {
            for (int nodeInSet1 = 0; nodeInSet1 < size1; nodeInSet1++) {
                if (!visited[nodeInSet1]) {
                    int minCost = Integer.MAX_VALUE / 2;
                    for (int nodeInSet2 = 0; nodeInSet2 < size2; nodeInSet2++) {
                        if (((mask >> nodeInSet2) & 1) == 1) {
                            int cost = dp[mask][nodeInSet1][nodeInSet2];
                            minCost = Math.min(minCost, cost);
                        }
                    }

                    for (int nodeInSet2 = 0; nodeInSet2 < size2; nodeInSet2++) {
                        if (((mask >> nodeInSet2) & 1) == 1) {
                            int cost = dp[mask][nodeInSet1][nodeInSet2];
                            minCost = Math.min(minCost, cost);
                            for (int i = 0; i < size1; i++) {
                                if (!visited[i] && ((mask >> i) & 1) == 0) {
                                    int newMask = mask | (1 << i);
                                    dp[newMask][i][nodeInSet2] = Math.min(dp[newMask][i][nodeInSet2], cost + cost.get(i).get(nodeInSet2));
                                }
                            }
                        }
                    }

                    if (minCost != Integer.MAX_VALUE / 2) {
                        visited[nodeInSet1] = true;
                        for (int i = 0; i < size1; i++) {
                            dp[mask][i][nodeInSet1] = Math.min(dp[mask][i][nodeInSet1], minCost);
                        }
                    }
                }
            }
        }

        int minCost = Integer.MAX_VALUE / 2;
        for (int nodeInSet1 = 0; nodeInSet1 < size1; nodeInSet1++) {
            for (int nodeInSet2 = 0; nodeInSet2 < size2; nodeInSet2++) {
                minCost = Math.min(minCost, dp[(1 << size2) - 1][nodeInSet1][nodeInSet2]);
            }
        }

        return minCost;
    }
}

