import java.util.ArrayList;
import java.util.List;

public class Solution {
    public double getMinDistSum(int[][] positions) {
        int n = positions.length;
        double[] x = new double[n];
        double[] y = new double[n];

        for (int i = 0; i < n; i++) {
            x[i] = positions[i][0];
            y[i] = positions[i][1];
        }

        double sumX = 0, sumY = 0;
        for (double xi : x) {
            sumX += xi;
        }
        for (double yi : y) {
            sumY += yi;
        }

        double centroidX = sumX / n;
        double centroidY = sumY / n;

        double distSum = 0;
        for (int i = 0; i < n; i++) {
            double dx = x[i] - centroidX;
            double dy = y[i] - centroidY;
            distSum += Math.sqrt(dx * dx + dy * dy);
        }

        double learningRate = 1e-7;

        while (true) {
            double newDistSum = 0;
            for (int i = 0; i < n; i++) {
                double dx = x[i] - centroidX;
                double dy = y[i] - centroidY;
                double dist = Math.sqrt(dx * dx + dy * dy);
                newDistSum += dist;

                double newX = x[i] - (dx / dist) * learningRate;
                double newY = y[i] - (dy / dist) * learningRate;

                x[i] = newX;
                y[i] = newY;
            }

            centroidX = sumX / n;
            centroidY = sumY / n;

            newDistSum += Math.sqrt((centroidX - sumX / n) * (centroidX - sumX / n) + (centroidY - sumY / n) * (centroidY - sumY / n));

            if (Math.abs(newDistSum - distSum) < 1e-5) {
                break;
            }

            distSum = newDistSum;
        }

        return distSum;
    }
}

