    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int[] firstNonZeroInRow = new int[n];

        for (int i = 0; i < n; i++) {
            int j = 0;
            while (j < n && grid[i][j] == 0) {
                j++;
            }
            if (j != n) {
                firstNonZeroInRow[i] = j;
            }
        }

        int swaps = 0;
        for (int i = 0; i < n - 1; i++) {
            if (firstNonZeroInRow[i] > i + 1) {
                int indexToSwap = findIndexToSwap(firstNonZeroInRow, i);
                swap(firstNonZeroInRow, i, indexToSwap);
                swaps++;
            }
        }

        return firstNonZeroInRow[n - 1] <= n ? swaps : 1;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private int findIndexToSwap(int[] firstNonZeroInRow, int i) {
        for (int j = i + 1; j < firstNonZeroInRow.length; j++) {
            if (firstNonZeroInRow[j] > i + 1 && firstNonZeroInRow[j] < firstNonZeroInRow[i]) {
                return j;
            }
        }

        return -1;
    }
}

