public class Solution {
    public String reorderSpaces(String text) {
        String[] words = text.trim().split(" +");
        int totalSpace = text.length() - text.replace(" ", "").length();
        StringBuilder sb = new StringBuilder();

        if (words.length == 1) {
            for (int i = 0; i < totalSpace; i++) {
                sb.append(" ");
            }
            return words[0] + sb.toString();
        }

        int spaceBetweenWords = totalSpace / (words.length - 1);
        int extraSpaces = totalSpace % (words.length - 1);

        for (int i = 0; i < words.length - 1; i++) {
            if (i == 0) {
                sb.append(words[i]);
            } else {
                for (int j = 0; j < spaceBetweenWords; j++) {
                    sb.append(" ");
                }
                sb.append(words[i]);
            }

            if (extraSpaces > 0) {
                extraSpaces--;
                sb.append(" ");
            }
        }

        sb.append(words[words.length - 1]);

        return sb.toString();
    }
}

