public class Solution {
    public int countPairs(TreeNode root, int distance) {
        return dfs(root, distance);
    }

    private int dfs(TreeNode node, int distance) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 1;
        }
        int[] count = new int[]{0};
        helper(node, distance, count);
        return count[0];
    }

    private void helper(TreeNode node, int distance, int[] count) {
        if (node == null || distance <= 0) {
            return;
        }
        if (node.left == null && node.right == null) {
            count[0]++;
            return;
        }
        distance--;
        helper(node.left, distance, count);
        helper(node.right, distance, count);
    }
}

