import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minDays(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        int m = grid.length, n = grid[0].length;
        boolean[] visited = new boolean[m * n];
        int countIslands = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i * n + j] && grid[i][j] == 1) {
                    dfs(grid, visited, i, j);
                    countIslands++;
                }
            }
        }

        if (countIslands > 1) return 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    int days = dfs2(grid, visited, i, j);
                    grid[i][j] = 1;
                    return days + 1;
                }
            }
        }

        return -1;
    }

    private void dfs(int[][] grid, boolean[] visited, int i, int j) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i * grid[0].length + j] || grid[i][j] == 0)
            return;

        visited[i * grid[0].length + j] = true;
        dfs(grid, visited, i - 1, j);
        dfs(grid, visited, i + 1, j);
        dfs(grid, visited, i, j - 1);
        dfs(grid, visited, i, j + 1);
    }

    private int dfs2(int[][] grid, boolean[] visited, int i, int j) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i * grid[0].length + j] || grid[i][j] == 0)
            return 1;

        visited[i * grid[0].length + j] = true;
        int days = dfs2(grid, visited, i - 1, j);
        if (days > 0) return days;
        days = dfs2(grid, visited, i + 1, j);
        if (days > 0) return days;
        days = dfs2(grid, visited, i, j - 1);
        if (days > 0) return days;
        days = dfs2(grid, visited, i, j + 1);

        return 0;
    }
}

