import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxNonOverlapping(int[] nums, int target) {
        Map<Integer, Integer> prefixSum = new HashMap<>();
        int currentSum = 0;
        int count = 0;

        for (int i = 0; i < nums.length; i++) {
            currentSum += nums[i];

            if (currentSum == target) {
                count++;
                currentSum = 0;
            } else if (prefixSum.containsKey(currentSum - target)) {
                int prevIndex = prefixSum.get(currentSum - target);
                count++;
                for (int j = prevIndex + 1; j < i; j++) {
                    currentSum -= nums[j];
                    if (currentSum == target) {
                        count++;
                        break;
                    }
                }
                prefixSum.clear();
            } else {
                prefixSum.put(currentSum, i);
            }
        }

        return count;
    }
}

