        PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> b[1] - a[1]);
        queue.offer(new int[]{start, 1});

        while (!queue.isEmpty()) {
            int[] node = queue.poll();

            if (node[0] == end) return node[1] / 100000.0;

            for (int[] neighbor : graph.get(node[0])) {
                if (maxProbability[node[0]] * neighbor[1] > maxProbability[neighbor[0]]) {
                    maxProbability[neighbor[0]] = maxProbability[node[0]] * neighbor[1];
                    queue.offer(new int[]{neighbor[0], (int) (maxProbability[neighbor[0]] * 100000)});
                }
            }
        }

