public class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length;
        int n = targetGrid[0].length;
        Set<Integer> printedColors = new HashSet<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!printedColors.contains(targetGrid[i][j])) {
                    int[] colorBound = getColorBound(targetGrid, targetGrid[i][j], m, n);
                    if (colorBound == null) return false;

                    dfs(targetGrid, printedColors, colorBound[0], colorBound[1], colorBound[2], colorBound[3]);
                }
            }
        }

        return true;
    }

    private int[] getColorBound(int[][] targetGrid, int color, int m, int n) {
        int minI = Integer.MAX_VALUE;
        int maxI = Integer.MIN_VALUE;
        int minJ = Integer.MAX_VALUE;
        int maxJ = Integer.MIN_VALUE;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (targetGrid[i][j] == color) {
                    minI = Math.min(minI, i);
                    maxI = Math.max(maxI, i);
                    minJ = Math.min(minJ, j);
                    maxJ = Math.max(maxJ, j);
                }
            }
        }

        if (minI > maxI || minJ > maxJ) return null;

        return new int[]{minI, minJ, maxI, maxJ};
    }

    private void dfs(int[][] targetGrid, Set<Integer> printedColors, int minI, int minJ, int maxI, int maxJ) {
        for (int i = minI; i <= maxI; i++) {
            for (int j = minJ; j <= maxJ; j++) {
                if (!printedColors.contains(targetGrid[i][j])) {
                    printedColors.add(targetGrid[i][j]);

                    int[] colorBound = getColorBound(targetGrid, targetGrid[i][j], maxI + 1, maxJ + 1);
                    if (colorBound == null) return;

                    dfs(targetGrid, printedColors, colorBound[0], colorBound[1], colorBound[2], colorBound[3]);
                }
            }
        }
    }
}

