                for (int j = start + 1; j <= end; j++) {
                    last[s.charAt(j) - 'a'] = Math.max(last[s.charAt(j) - 'a'], i);
                }
                dq.addLast(end);
            }
        }

        while (!dq.isEmpty()) {
            int end = dq.removeFirst();
            if (start == -1) start = end;
            for (int j = start + 1; j <= end; j++) {
                last[s.charAt(j) - 'a'] = Math.max(last[s.charAt(j) - 'a'], i);
            }
        }

        Map<Integer, List<String>> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (last[i] == i) continue;
            int startIdx = last[s.charAt(i) - 'a'];
            int endIdx = dq.removeFirst();
            while (!dq.isEmpty() && last[s.charAt(endIdx) - 'a'] != endIdx) {
                endIdx = dq.removeFirst();
            }
            map.computeIfAbsent(startIdx, k -> new ArrayList<>()).add(s.substring(startIdx, endIdx + 1));
        }

        List<String> res = new ArrayList<>();
        for (List<String> list : map.values()) {
            Collections.sort(list, Comparator.comparingInt(String::length));
            res.addAll(list);
        }
        return res;
    }
}

