public class Solution {
    public int numSplits(String s) {
        Set<Character> set = new HashSet<>();
        int count = 0, leftCount = 0;

        for (char c : s.toCharArray()) {
            if (!set.contains(c)) {
                set.add(c);
                leftCount++;
            }
        }

        for (int i = 0; i < s.length() - 1; i++) {
            char c = s.charAt(i);
            set.remove(c);

            int rightCount = s.substring(i + 1).chars().distinct().count();

            if (leftCount == rightCount) count++;

            set.add(c);
        }

        return count;
    }
}

