import java.util.*;

public class Solution {
    private static final long MOD = (long) 1e9 + 7;

    public int maxProductPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;

        long[][] dpMax = new long[m][n];
        long[][] dpMin = new long[m][n];

        dpMax[0][0] = dpMin[0][0] = grid[0][0];

        for (int i = 1; i < m; i++) {
            dpMax[i][0] = dpMin[i][0] = dpMin[i - 1][0] * grid[i][0];
            if (dpMax[i - 1][0] > 0) {
                dpMax[i][0] += dpMax[i - 1][0];
            } else {
                dpMax[i][0] -= dpMax[i - 1][0];
            }
        }

        for (int j = 1; j < n; j++) {
            dpMax[0][j] = dpMin[0][j] = dpMin[0][j - 1] * grid[0][j];
            if (dpMax[0][j - 1] > 0) {
                dpMax[0][j] += dpMax[0][j - 1];
            } else {
                dpMax[0][j] -= dpMax[0][j - 1];
            }
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                long up1 = grid[i][j], up2 = dpMax[i - 1][j];
                if (up2 > 0) {
                    up1 += up2;
                } else {
                    up1 -= up2;
                }

                long left1 = grid[i][j], left2 = dpMax[i][j - 1];
                if (left2 > 0) {
                    left1 += left2;
                } else {
                    left1 -= left2;
                }

                dpMax[i][j] = Math.max(up1, left1);
                long up3 = grid[i][j], up4 = dpMin[i - 1][j];
                if (up4 > 0) {
                    up3 += up4;
                } else {
                    up3 -= up4;
                }

                long left3 = grid[i][j], left4 = dpMin[i][j - 1];
                if (left4 > 0) {
                    left3 += left4;
                } else {
                    left3 -= left4;
                }

                dpMin[i][j] = Math.min(up3, left3);
            }
        }

        return (int) (dpMax[m - 1][n - 1] % MOD);
    }
}

