public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private int ones, zeros, total;
    private boolean[] seen;

    public int numWays(String s) {
        ones = 0;
        zeros = 0;
        total = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') {
                ones++;
            } else {
                zeros++;
            }
            total++;
        }

        seen = new boolean[ones + 1];
        return ways(0, 0);
    }

    private int ways(int i, int j) {
        if (i > ones / 3 || j > ones - ones / 3) {
            return 0;
        }
        if (i == ones / 3 && j == ones - ones / 3) {
            return 1;
        }

        if (seen[i + j]) {
            return 0;
        }
        seen[i + j] = true;

        int res = ways(i + 1, j);
        for (int k = i; k < total - 2 * ones / 3; k++) {
            res += ways(k + 1, j + 1);
        }

        return res % MOD;
    }
}

