public class Solution {
    public int getLengthOfOptimalCompression(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);
        dp[0][0] = 0;
        for (int i = 1; i <= n; ++i) {
            char c = s.charAt(i - 1);
            int cnt = 1;
            for (int j = i - 1; j >= 1 && s.charAt(j - 1) == c; --j) {
                cnt++;
            }
            for (int x = k; x >= 0; --x) {
                if (cnt > 1 || (i > 1 && cnt > 9)) {
                    dp[i][x] = Math.min(dp[i][x], dp[j - 1][x + (i - j)] + compress(cnt));
                }
                dp[i][x] = Math.min(dp[i][x], dp[i - 1][x]);
            }
        }
        return dp[n][k];
    }

    private int compress(int n) {
        if (n < 10) return n;
        else if (n < 100) return 2;
        else if (n < 1000) return 3;
        else return 4;
    }
}

