public class Solution {
    public boolean containsCycle(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        Set<String> visited = new HashSet<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited.contains(i + "," + j)) {
                    Queue<int[]> queue = new LinkedList<>();
                    queue.offer(new int[] {i, j});
                    visited.add(i + "," + j);

                    Set<String> path = new HashSet<>();
                    path.add(i + "," + j);

                    while (!queue.isEmpty()) {
                        int[] curr = queue.poll();
                        char c = grid[curr[0]][curr[1]];

                        if (path.size() > 3 && path.contains(curr[0] + "," + curr[1])) {
                            return true;
                        }

                        for (int[] dir : new int[][] {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                            int x = curr[0] + dir[0];
                            int y = curr[1] + dir[1];

                            if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] == c && !visited.contains(x + "," + y)) {
                                queue.offer(new int[] {x, y});
                                visited.add(x + "," + y);
                                path.add(x + "," + y);
                            }
                        }
                    }
                }
            }
        }

        return false;
    }
}

