public class Solution {
    public int longestAwesome(String s) {
        int n = s.length();
        int[] dp = new int[n + 1];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1];
            char c = s.charAt(i - 1);

            for (char j = 'a'; j <= 'z'; j++) {
                int idx = c == j ? i : dp[i - 1];
                if ((c ^ j) % 2 == 0 && dp[idx] != -1) {
                    dp[i] = Math.max(dp[i], i - idx);
                }
            }

            for (char j = 'a'; j <= 'z'; j++) {
                int idx = c == j ? i : dp[i - 1];
                if ((c ^ j) % 2 != 0 && dp[idx] != -1) {
                    dp[i] = Math.max(dp[i], i - idx);
                }
            }
        }

        return dp[n];
    }
}

