public class Solution {
    public int minCost(int n, int[] cuts) {
        Arrays.sort(cuts);
        cuts = Arrays.copyOfRange(cuts, 1, cuts.length - 1);

        int m = cuts.length + 2;
        int[][] dp = new int[m][m];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE / 2);
        }

        for (int i = 0; i < m; i++) {
            dp[i][i] = 0;
        }
        for (int len = 1; len < m; len++) {
            for (int l = 0; l + len < m; l++) {
                int r = l + len;
                if (r == n) {
                    dp[l][r] = cuts[r - 1];
                } else {
                    for (int k = l; k <= r; k++) {
                        dp[l][r] = Math.min(dp[l][r], dp[l][k] + dp[k][r]);
                    }
                    if (cuts.length > 0) {
                        int index = Arrays.binarySearch(cuts, n);
                        if (index < 0) {
                            index = -index - 1;
                        }
                        dp[l][r] = Math.min(dp[l][r], cuts[index] + (l == 0 ? 0 : dp[0][l - 1]) + (r == m - 1 ? 0 : dp[r + 1][m - 1]));
                    }
                }
            }
        }

        return dp[0][n];
    }
}

