public class Solution {
    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        int n = locations.length;
        long[][] dp = new long[n][fuel + 1];
        for (long[] row : dp) Arrays.fill(row, -1);

        return dfs(locations, start, finish, fuel, dp);
    }

    private int dfs(int[] locations, int cur, int end, int fuel, long[][] dp) {
        if (cur == end) return 1;
        if (fuel < 0 || dp[cur][fuel] != -1) return 0;

        for (int i = 0; i < locations.length; i++) {
            if (i != cur && fuel >= Math.abs(locations[cur] - locations[i])) {
                dp[cur][fuel] += dfs(locations, i, end, fuel - Math.abs(locations[cur] - locations[i]), dp);
                dp[cur][fuel] %= 1000000007;
            }
        }

        return (int) dp[cur][fuel];
    }
}

