public class Solution {
    public List<Integer> mostVisited(int n, int[] rounds) {
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < rounds.length - 1; i++) {
            if (rounds[i] == rounds[i + 1]) continue;
            if (rounds[i] > rounds[i + 1]) {
                for (int j = rounds[i]; j <= n; j++) result.add(j);
                for (int j = 1; j <= rounds[i + 1]; j++) result.add(j);
            } else {
                for (int j = rounds[i]; j <= rounds[i + 1]; j++) result.add(j);
            }
        }
        if (rounds[0] > rounds[rounds.length - 1]) {
            for (int j = rounds[rounds.length - 1]; j <= n; j++) result.add(j);
            for (int j = 1; j <= rounds[0]; j++) result.add(j);
        } else {
            for (int j = rounds[rounds.length - 1]; j <= rounds[0]; j++) result.add(j);
        }
        return removeDuplicates(result);
    }

    private List<Integer> removeDuplicates(List<Integer> list) {
        List<Integer> result = new ArrayList<>();
        int last = Integer.MIN_VALUE;
        for (int i : list) {
            if (i != last) {
                result.add(i);
                last = i;
            }
        }
        return result;
    }
}

