public class Solution {
    public int findLatestStep(int[] arr, int m) {
        int n = arr.length;
        int[] leftCount = new int[n + 2];
        int[] rightCount = new int[n + 2];

        for (int i = 0; i < n; i++) {
            int x = arr[i];
            leftCount[x] += 1;
            rightCount[x] += 1;

            if (x - 1 >= 0) {
                leftCount[x - 1] -= 1;
            }
            if (x + 1 <= n - 1) {
                rightCount[x + 1] -= 1;
            }

            int currentLeft = x - leftCount[x - 1];
            int currentRight = x + rightCount[x + 1];

            if (currentLeft == m || currentRight == m) {
                return i + 1;
            }
        }

        return -1;
    }
}

