import java.util.*;

public class Solution {
    public int maxNumEdgesToRemove(int n, int[][] edges) {
        UnionFind uf1 = new UnionFind(n);
        UnionFind uf2 = new UnionFind(n);

        int count = 0;
        for (int[] edge : edges) {
            if ((edge[0] == 3 && uf1.union(edge[1], edge[2])) || (edge[0] == 1 && uf1.union(edge[1], edge[2]))) {
                uf2.union(edge[1], edge[2]);
                count++;
            } else if ((edge[0] == 3 && uf2.union(edge[1], edge[2])) || (edge[0] == 2 && uf2.union(edge[1], edge[2]))) {
                uf1.union(edge[1], edge[2]);
                count++;
            }
        }

        int result = n - 1;
        if (uf1.count != 1 || uf2.count != 1) return -1;

        for (int[] edge : edges) {
            if ((edge[0] == 3 && !uf1.union(edge[1], edge[2])) || (edge[0] == 1 && !uf1.union(edge[1], edge[2]))) result--;
            else if ((edge[0] == 3 && !uf2.union(edge[1], edge[2])) || (edge[0] == 2 && !uf2.union(edge[1], edge[2]))) result--;
        }

        return Math.max(result, count);
    }
}

class UnionFind {
    int[] parent;
    int[] size;

    public UnionFind(int n) {
        parent = new int[n];
        size = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = -1;
            size[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] == -1) return x;

        parent[x] = find(parent[x]);
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (size[rootX] > size[rootY]) {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            } else {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            }
        }
    }

    public int count() {
        int count = 0;

        for (int i : parent) if (i == -1) count++;

        return count;
    }
}

