public class Solution {
    public long minSum(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int m = nums2.length;

        // Count the number of zeros in both arrays
        int zeroCount1 = 0;
        for (int i : nums1) {
            if (i == 0) {
                zeroCount1++;
            }
        }

        int zeroCount2 = 0;
        for (int i : nums2) {
            if (i == 0) {
                zeroCount2++;
            }
        }

        // If the total number of zeros is odd, it's impossible to make both arrays sum up to the same value
        if ((zeroCount1 + zeroCount2) % 2 != 0) {
            return -1;
        }

        long sum = 0;

        // Replace all zeros with positive integers and calculate the total sum
        for (int i = 0; i < n; i++) {
            if (nums1[i] == 0) {
                nums1[i] = zeroCount1-- + 1;
                sum += nums1[i];
            } else {
                sum += nums1[i];
            }
        }

        for (int i = 0; i < m; i++) {
            if (nums2[i] == 0) {
                nums2[i] = zeroCount2-- + 1;
                sum += nums2[i];
            } else {
                sum += nums2[i];
            }
        }

        // If the total sum is odd, it's impossible to make both arrays sum up to the same value
        if (sum % 2 != 0) {
            return -1;
        }

        // Return half of the total sum as the minimum equal sum
        return sum / 2;
    }
}

