public class Solution {
    public int minimumCost(String source, String target, char[] original, char[] changed, int[] cost) {
        Map<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < cost.length; i++) {
            if (!map.containsKey(original[i])) {
                map.put(original[i], cost[i]);
            } else {
                map.put(original[i], Math.min(map.get(original[i]), cost[i]));
            }
        }

        int n = source.length();
        long[][] dp = new long[n + 1][n + 1];
        for (long[] row : dp) {
            Arrays.fill(row, Long.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            char cSource = source.charAt(i - 1);
            char cTarget = target.charAt(i - 1);

            if (!map.containsKey(cSource)) {
                return -1;
            }

            long minCost = map.get(cSource);
            for (int j = 0; j <= i; j++) {
                dp[i][j] = Math.min(dp[i][j], dp[i - 1][j]);
                if (cTarget == cSource) {
                    dp[i][j + 1] = Math.min(dp[i][j + 1], dp[i - 1][j] + minCost);
                } else if (map.containsKey(cTarget)) {
                    long costChange = map.get(cTarget);
                    dp[i][j + 1] = Math.min(dp[i][j + 1], dp[i - 1][j] + costChange);
                }
            }
        }

        return (int) dp[n][n];
    }
}

