        Arrays.sort(coins);
        TreeSet<Integer> set = new TreeSet<>();
        for (int i : coins) {
            set.add(i);
        }
        int ans = 0;
        for (int i = 1; i <= target; i++) {
            if (!set.contains(i)) {
                int lo = -1, hi = coins.length - 1;
                while (lo < hi) {
                    int mid = (lo + hi + 1) / 2;
                    if (coins[mid] > i) {
                        hi = mid - 1;
                    } else {
