public class Solution {
    public int findMaximumLength(int[] nums) {
        int n = nums.length;
        int[][] dp = new int[n][2];

        for (int i = 0; i < n; i++) {
            if (i == 0 || nums[i] >= nums[i - 1]) {
                dp[i][0] = 1;
                dp[i][1] = 1;
            } else {
                int max = Math.max(dp[i - 1][0], dp[i - 1][1]);
                if (nums[i] > nums[max - 1]) {
                    dp[i][0] = max + 1;
                }
                if (max == 0 || nums[i] >= nums[max - 2]) {
                    dp[i][1] = Math.max(max, dp[i - 1][1]);
                } else {
                    int sum = 0;
                    for (int j = i; j > max - 1; j--) {
                        sum += nums[j];
                        if (sum >= nums[max - 2]) {
                            dp[i][1] = Math.max(max, dp[j - 1][1]);
                            break;
                        }
                    }
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, Math.max(dp[i][0], dp[i][1]));
        }

        return ans - 1;
    }
}

