public class Solution {
    public List<String> getWordsInLongestSubsequence(int n, String[] words, int[] groups) {
        Map<Integer, List<Integer>> groupMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (!groupMap.containsKey(groups[i])) {
                groupMap.put(groups[i], new ArrayList<>());
            }
            groupMap.get(groups[i]).add(i);
        }

        int maxLen = 1;
        List<String> res = new ArrayList<>();
        for (int g : groups) {
            List<Integer> indices = groupMap.get(g);
            if (indices.size() < 2) continue;

            int[] dp = new int[indices.size()];
            Arrays.fill(dp, 1);

            for (int i = 0; i < indices.size(); i++) {
                for (int j = 0; j < i; j++) {
                    if (words[indices.get(i)].length() == words[indices.get(j)].length()) {
                        int diffCount = 0;
                        for (int k = 0; k < words[indices.get(i)].length(); k++) {
                            if (words[indices.get(i)].charAt(k) != words[indices.get(j)].charAt(k)) {
                                diffCount++;
                            }
                        }

                        if (diffCount == 1 && dp[j] + 1 > dp[i]) {
                            dp[i] = dp[j] + 1;
                        }
                    }
                }
            }

            int maxIdx = -1;
            for (int i = 0; i < indices.size(); i++) {
                if (dp[i] > maxLen) {
                    maxLen = dp[i];
                    maxIdx = i;
                } else if (dp[i] == maxLen && maxIdx == -1) {
                    maxIdx = i;
                }
            }

            if (maxIdx != -1) {
                res.clear();
                int idx = maxIdx;
                while (idx >= 0) {
                    res.add(0, words[indices.get(idx)]);
                    for (int j = 0; j < indices.size(); j++) {
                        if (dp[j] == dp[idx] - 1 && groups[indices.get(j)] != groups[indices.get(idx)]) {
                            idx = j;
                            break;
                        }
                    }
                }

                return res;
            }
        }

        return new ArrayList<>();
    }
}

