public class Solution {
    public int minChanges(String s) {
        int n = s.length();
        int[][] dp = new int[n + 1][2];

        for (int i = 0; i <= n; i++) {
            if (i == 0) {
                dp[i][0] = 0;
                dp[i][1] = 0;
            } else if ((i & 1) != 0) {
                int prevEven = i - 1 >= 0 ? dp[i - 1][0] : 0;
                int prevOdd = i - 2 >= 0 ? dp[i - 2][1] : 0;
                dp[i][0] = Math.min(prevEven, prevOdd) + (s.charAt(i - 1) == '1' ? 0 : 1);
                dp[i][1] = prevEven + (s.charAt(i - 1) == '0' ? 0 : 1);
            } else {
                int prevEven = i - 2 >= 0 ? dp[i - 2][0] : 0;
                int prevOdd = i - 3 >= 0 ? dp[i - 3][1] : 0;
                dp[i][0] = Math.min(prevEven, prevOdd) + (s.charAt(i - 1) == '0' ? 0 : 1);
                dp[i][1] = prevEven + (s.charAt(i - 1) == '1' ? 0 : 1);
            }
        }

        return Math.min(dp[n][0], dp[n][1]);
    }
