public class Solution {
    public int countSubMultisets(List<Integer> nums, int l, int r) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        long mod = (long) Math.pow(10, 9) + 7;
        long[][] dp = new long[freq.size() + 1][r + 1];
        for (int i = 0; i <= freq.size(); i++) {
            Arrays.fill(dp[i], -1);
        }

        return (int) helper(freq, l, r, 0, 0, dp, mod);
    }

    private long helper(Map<Integer, Integer> freq, int l, int r, int idx, int sum, long[][] dp, long mod) {
        if (idx == freq.size()) {
            return sum >= l && sum <= r ? 1 : 0;
        }

        if (dp[idx][sum] != -1) {
            return dp[idx][sum];
        }

        long ans = 0;
        int maxFreq = freq.getOrDefault(freq.keySet().iterator().next(), 0);
        for (int i = 0; i <= maxFreq; i++) {
            int newSum = sum + i * freq.keySet().iterator().next();
            if (newSum >= l && newSum <= r) {
                ans += helper(freq, l, r, idx + 1, newSum, dp, mod);
            }
        }

        return dp[idx][sum] = ans % mod;
    }
}

