public class Solution {
    public long minIncrementOperations(int[] nums, int k) {
        int n = nums.length;
        int[] buckets = new int[n];

        for (int num : nums) {
            int bucketIndex = Math.max(num - k + 1, 0);
            buckets[bucketIndex]++;
        }

        long operations = 0;
        int prevBucketSize = 0;

        for (int i = 0; i < n; i++) {
            if (buckets[i] == 0) continue;

            int currentBucketSize = buckets[i];
            operations += Math.max(0, currentBucketSize - prevBucketSize);
            prevBucketSize = currentBucketSize;

            if (i + 1 < n) {
                buckets[i + 1] += buckets[i];
            }
        }

        return operations;
    }
}

