        int minSum = Integer.MAX_VALUE;
        for (int i = 1; i < n - 1; i++) {
            if (leftMax[i - 1] < nums[i] && nums[i] > rightMin[i + 1]) {
                minSum = Math.min(minSum, leftMax[i - 1] + nums[i] + rightMin[i + 1]);
            }
        }

        return minSum == Integer.MAX_VALUE ? -1 : minSum;
    }
}

