public class Solution {
    public long maxSpending(int[][] values) {
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (int i = 0; i < values.length; i++) {
            for (int j = 0; j < values[i].length; j++) {
                pq.add(new Node(values[i][j] * (i + 1)));
            }
        }

        long totalSpent = 0;
        while (!pq.isEmpty()) {
