        int n = grid.length;
        boolean[] isChampion = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!isChampion[i]) {
                for (int j = 0; j < n; j++) {
                    if (i != j && !grid[j][i] && grid[i][j]) {
                        isChampion[i] = true;
                        break;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (!isChampion[i]) {
                return i;
            }
        }

        for (int i = 0; i < n; i++) {
            boolean isStrongerThanAny = true;
            for (int j = 0; j < n; j++) {
                if (i != j && grid[j][i]) {
                    isStrongerThanAny = false;
                    break;
                }
            }
            if (isStrongerThanAny) {
                return i;
            }
        }

        return -1;
    }
}

