public class Solution {
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        long maxScore = 0;
        boolean[] visited = new boolean[values.length];
        dfs(graph, values, visited, -1);

        return maxScore;
    }

    private void dfs(List<List<Integer>> graph, int[] values, boolean[] visited, int node) {
        if (node == -1) {
            for (int i = 0; i < values.length; i++) {
                if (!visited[i]) {
                    long score = 0;
                    long pathSum = 0;

                    dfs(graph, values, visited, i);

                    maxScore = Math.max(maxScore, score + pathSum);
                }
            }
        } else {
            visited[node] = true;

            for (int neighbor : graph.get(node)) {
                if (!visited[neighbor]) {
                    long score = 0;
                    long pathSum = values[neighbor];

                    dfs(graph, values, visited, neighbor);

                    maxScore = Math.max(maxScore, score + pathSum);
                }
            }
        }
    }
}

