public class Solution {
    public int minimumChanges(String s, int k) {
        int n = s.length();
        if (k > n / 2 + 1) return -1;

        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = 0;
            if (i > 0) dp[i][i-1] = 1;
        }

        for (int len = 2; len <= n; len++) {
            for (int start = 0; start + len - 1 < n; start++) {
                int end = start + len - 1;
                if (s.charAt(start) == s.charAt(end)) dp[start][end] = dp[start+1][end-1];
                else dp[start][end] = Math.min(dp[start+1][end], dp[start][end-1]) + 1;
            }
        }

        int minChanges = Integer.MAX_VALUE;
        for (int i = 0; i <= n - k; i++) {
            int changes = 0;
            for (int j = 0; j < k - 1; j++) {
                changes += dp[i + j][i + j + k - 1];
            }
            minChanges = Math.min(minChanges, changes);
        }

        return minChanges;
    }
}

