public class Solution {
    public int maximizeSquareHoleArea(int n, int m, int[] hBars, int[] vBars) {
        Set<Integer> horizontal = new HashSet<>();
        for (int i : hBars) {
            horizontal.add(i);
        }

        Set<Integer> vertical = new HashSet<>();
        for (int i : vBars) {
            vertical.add(i);
        }

        int maxArea = 0;
        for (int i = 2; i <= n + 1; i++) {
            if (horizontal.contains(i)) {
                for (int j = 2; j <= m + 1; j++) {
                    if (vertical.contains(j)) {
                        int minSide = Math.min(Math.min(i, j), Math.min(n - i + 1, m - j + 1));
                        maxArea = Math.max(maxArea, minSide * minSide);
                    }
                }
            }
        }

        return maxArea;
    }
}

