public class Solution {
    public int missingInteger(int[] nums) {
        int n = nums.length;
        int sum = 0, maxNum = Integer.MIN_VALUE, count = 1;

        for (int i = 0; i < n; i++) {
            if (i == 0 || nums[i] != nums[i - 1]) {
                count++;
                maxNum = Math.max(maxNum, nums[i]);
                sum += nums[i];
            }
