public class Solution {
    public int[] leftmostBuildingQueries(int[] heights, int[][] queries) {
        int n = heights.length;
        int m = queries.length;

        int[] ans = new int[m];
        for (int i = 0; i < m; i++) {
            ans[i] = -1;
        }

        for (int i = 0; i < m; i++) {
            int a = queries[i][0], b = queries[i][1];

            int l = 0, r = n - 1;

            while (l <= r) {
                int mid = l + (r - l) / 2;
                if (heights[mid] > heights[a]) {
                    r = mid - 1;
                } else if (heights[mid] < heights[a]) {
                    ans[i] = mid;
                    l = mid + 1;
                } else {
                    l = mid + 1;
                }
            }

            int j = b;

            while (j >= 0) {
                if (heights[j] > heights[b]) {
                    break;
                } else if (heights[j] < heights[b]) {
                    ans[i] = Math.max(ans[i], j);
                    break;
                } else {
                    j--;
                }
            }

        }

        return ans;
    }
}

