public class Solution {
    public long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        long[] coin = new long[n];
        Arrays.fill(coin, 1);

        int[] subtreeSize = new int[n];

        dfs(graph, cost, coin, subtreeSize, -1, 0);

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[2]));
        for (int i = 0; i < n; i++) {
            if (subtreeSize[i] >= 3) {
                int[] temp = {i, cost[i], subtreeSize[i]};
                pq.offer(temp);
            }
        }

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            long maxProduct = -1;
            for (int i = 0; i < n; i++) {
                if (subtreeSize[i] >= 3) {
                    int[] temp = {i, cost[i], subtreeSize[i]};
                    pq.offer(temp);
                }
            }

            while (!pq.isEmpty()) {
                int[] top2 = pq.poll();
                long product = (long) top[1] * top2[1] * cost[top[0]];
                if (product > maxProduct && product >= 0) {
                    maxProduct = product;
                }
            }

            coin[top[0]] = maxProduct;
        }

        return coin;
    }

    private void dfs(List<Integer>[] graph, int[] cost, long[] coin, int[] subtreeSize, int parent, int node) {
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(graph, cost, coin, subtreeSize, node, child);
                subtreeSize[node] += subtreeSize[child];
            }
        }

        if (subtreeSize[node] < 3) {
            return;
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[2]));
        for (int child : graph[node]) {
            if (child != parent) {
                int[] temp = {child, cost[child], subtreeSize[child]};
                pq.offer(temp);
            }
        }

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            long product = (long) top[1] * cost[top[0]] * cost[node];
            if (product > 0 && product >= coin[node]) {
                coin[node] = product;
            }
        }
    }
}

