public class Solution {
    public int minimumCost(String source, String target, String[] original, String[] changed, int[] cost) {
        int n = source.length();
        boolean[][] dp = new boolean[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], false);
        }
        dp[0][0] = true;
        HashMap<String, Integer> map = new HashMap<>();
        HashSet<Integer> set = new HashSet<>();
        for (int i = 0; i < original.length; i++) {
            if (!map.containsKey(original[i])) {
                map.put(original[i], cost[i]);
                set.add(cost[i]);
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= n - i; j++) {
                int k = j + i;
                if (dp[j][k]) {
                    String s = source.substring(j, k);
                    if (map.containsKey(s)) {
                        dp[j + 1][k] |= true;
                        dp[j][k - 1] |= true;
                        for (int l : set) {
                            if (l == map.get(s)) {
                                dp[j][k] |= true;
                            }
                        }
                    }
                }
            }
        }
        return dp[n][n] ? map.getOrDefault(source, Integer.MAX_VALUE) : -1;
    }
}

