import java.util.Arrays;
import java.util.ArrayList;

public class Solution {
    public int[][] divideArray(int[] nums, int k) {
        Arrays.sort(nums);
        ArrayList<int[]> result = new ArrayList<>();
        int start = 0;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] - nums[start] > k) {
                start = i;
                result.add(new int[]{nums[start]});
            } else {
                result.get(result.size() - 1)[result.get(result.size() - 1).length - 1] = nums[i];
            }
        }

        if (start != nums.length - 1 && nums[nums.length - 1] - nums[start] > k) {
            return new int[][]{};
        } else {
            result.get(result.size() - 1)[result.get(result.size() - 1).length] = nums[nums.length - 1];
            int[][] array = new int[result.size()][];
            for (int i = 0; i < result.size(); i++) {
                array[i] = Arrays.copyOf(result.get(i), result.get(i).length);
            }
            return array;
        }
    }
}

