        }

        boolean[] answer = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1], c = queries[i][2], d = queries[i][3];

            if (a == c) {
                answer[i] = true;
                continue;
            }

            String firstHalf = s.substring(a, Math.min(b, n / 2));
            String secondHalf = s.substring(n / 2, Math.min(c, n));

            int[] countFirstHalf = new int[26];
            for (char c1 : firstHalf.toCharArray()) {
                countFirstHalf[c1 - 'a']++;
            }

            int[] countSecondHalf = new int[26];
            for (char c1 : secondHalf.toCharArray()) {
                countSecondHalf[c1 - 'a']++;
            }

            boolean isPalindrome = true;
            for (int j = 0; j < 26; j++) {
                if (countFirstHalf[j] != countSecondHalf[j]) {
                    isPalindrome = false;
                    break;
                }
            }

            if (!isPalindrome) {
                answer[i] = false;
                continue;
            }

            int firstDifferentIndex = -1, lastDifferentIndex = -1;
            for (int j = 0; j < Math.min(b, n / 2); j++) {
                if (firstHalf.charAt(j) != secondHalf.charAt(c - d + j)) {
                    if (firstDifferentIndex == -1) firstDifferentIndex = j;
                    lastDifferentIndex = j;
                }
            }

            int leftIntervalLength = b - a + 1, rightIntervalLength = d - c + 1;

            boolean isPossible = false;
            if (leftIntervalLength >= lastDifferentIndex - firstDifferentIndex + 2) {
                isPossible = true;
            } else if (rightIntervalLength >= lastDifferentIndex - firstDifferentIndex + 2) {
                isPossible = true;
            }

            answer[i] = isPossible;
        }
        return answer;
    }

    private int n;

    public Solution() {
        this.n = s.length();
    }
}

