public class Solution {
    public long minimumSteps(String s) {
        int n = s.length();
        int whiteCount = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                whiteCount++;
            }
        }

        int blackCount = n - whiteCount;

        long steps = 0;
        for (int i = 0; i < whiteCount; i++) {
            while (i >= 0 && s.charAt(i) == '0') {
                i--;
            }
            if (i < 0) break;
            int j = n - blackCount + i;
            while (j < n && s.charAt(j) == '1') {
                j++;
            }

            if (i < j) {
                steps += Math.abs(i - j);
                char[] arr = s.toCharArray();
                char temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
                s = new String(arr);

                i--;
                blackCount--;
            } else break;
        }

        return steps + whiteCount;
    }
}

