            maxNums1 = maxNums2;
            maxNums2 = temp;
        }

        if (maxNums1 > maxNums2 * 2 || maxNums2 > maxNums1 * 2) {
            return -1;
        } else {
            int ops = 0;
            for (int i = 0; i < n; i++) {
                if (nums1[i] != maxNums1 && nums2[i] != maxNums2) {
                    int diff1 = Math.abs(maxNums1 - nums1[i]);
                    int diff2 = Math.abs(maxNums2 - nums2[i]);

                    ops += Math.min(diff1, diff2);
                }
            }

            return ops;
        }
    }
