public class Solution {
    public int findKOr(int[] nums, int k) {
        int n = nums.length;
        int[] count = new int[32];

        for (int num : nums) {
            for (int i = 0; i < 32; i++) {
                if ((num & (1 << i)) != 0) {
                    count[i]++;
                }
            }
        }

        int kOr = 0;
        for (int i = 0; i < 32; i++) {
