public class Solution {
    public int[][] constructProductMatrix(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        // Calculate prefix sums for rows and columns
        long[] rowPrefixSums = new long[n];
        long[] colPrefixSums = new long[m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                rowPrefixSums[i] += grid[i][j];
                colPrefixSums[j] += grid[i][j];
            }
        }

        // Calculate product matrix
        int[][] productMatrix = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                long product = rowPrefixSums[i] * colPrefixSums[j];
                if (product > Integer.MAX_VALUE) {
                    productMatrix[i][j] = -1;
                } else {
                    productMatrix[i][j] = (int) (product % 1000000007);
                }
            }
        }

        return productMatrix;
    }
}

