import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int maxArea(int m, int n, int[][] hFences, int[][] vFences) {
        Arrays.sort(hFences, (a, b) -> a[0] - b[0]);
        Arrays.sort(vFences, (a, b) -> a[0] - b[0]);

        Set<Integer> set = new HashSet<>();
        for (int[] fence : hFences) {
            set.add(fence[0]);
        }
        for (int[] fence : vFences) {
            set.add(fence[0]);
        }

        int maxSide = Math.min(m - 1, n - 1);
        int minSide = 1;
        while (minSide <= maxSide) {
            int mid = (maxSide + minSide) / 2;
            boolean isValid = true;

            for (int i : set) {
                if ((i >= 1 && i <= m - 1) && (i % mid == 0 || (m - 1) % mid == 0)) {
                    isValid = false;
                    break;
                }
            }

            if (!isValid) {
                minSide = mid + 1;
            } else {
                maxSide = mid - 1;
            }
        }

        return (int) ((maxSide * maxSide) % (Math.pow(10, 9) + 7));
    }
}

