import java.util.*;

public class Solution {
    public int collectCoins(int[][] edges, int[] coins, int k) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < edges.length + 1; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int n = coins.length;
        long[] dp = new long[n];
        dfs(graph, 0, -1, coins, k, dp);
        return (int) Math.max(dp[0] - k, 0);
    }

    private void dfs(List<List<Integer>> graph, int node, int parent, int[] coins, int k, long[] dp) {
        if (dp[node] != 0) return;
        dp[node] = coins[node];
        for (int child : graph.get(node)) {
            if (child == parent) continue;
            dfs(graph, child, node, coins, k, dp);
            dp[node] += Math.max(dp[child] - k, 0);
            long temp = dp[child];
            dp[child] = 0;
            int[] newCoins = Arrays.copyOf(coins, coins.length);
            for (int i = 0; i < newCoins.length; i++) {
                if (newCoins[i] >= 2) newCoins[i] /= 2;
            }
            dp[node] += Math.max(temp - k, 0);
        }
    }
}

