                        default:
                            sb.append(strNum).append("3");
                    }
                    if (isPrime(sb.toString())) {
                        count++;
                    }
                }
                primeCount.put(num, primeCount.getOrDefault(num, 0) + count);
            }
        }

        int maxCount = 0;
        int result = -1;
        for (Map.Entry<Integer, Integer> entry : primeCount.entrySet()) {
            if (entry.getValue() > maxCount && isPrime(String.valueOf(entry.getKey()))) {
