public class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0) {
                pq.offer(new int[]{nums[i], i});
            }
        }

        int m = changeIndices.length;
        int n = nums.length;

        int second = 1;
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int val = top[0];
            int idx = top[1];

            if (val == 0) {
                continue;
            }

            if (second <= m && changeIndices[second - 1] == idx) {
                second++;
                continue;
            }

            nums[idx]--;
            if (nums[idx] != 0) {
                pq.offer(new int[]{nums[idx], idx});
            }
        }

        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                return -1;
            }
        }

        return second <= m ? second : -1;
    }
}

