public class Solution {
    public int countSubmatrices(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        long[] prefixSum = new long[m + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                prefixSum[i + 1] += grid[i][j];
            }
        }

        int count = 0;
        for (int i = 0; i <= m; i++) {
            for (int j = i; j <= m; j++) {
                long sum = prefixSum[j] - (i > 0 ? prefixSum[i - 1] : 0);
