public class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0 && Math.abs(image[i][j] - image[i-1][j]) <= threshold) {
                    result[i][j] = result[i-1][j];
                } else if (j > 0 && Math.abs(image[i][j] - image[i][j-1]) <= threshold) {
                    result[i][j] = result[i][j-1];
                } else {
                    int sum = image[i][j];
                    int count = 1;

                    for (int x = Math.max(0, i-1); x < Math.min(m, i+2); x++) {
                        for (int y = Math.max(0, j-1); y < Math.min(n, j+2); y++) {
                            if ((x != i || y != j) && Math.abs(image[x][y] - image[i][j]) <= threshold) {
                                sum += image[x][y];
                                count++;
                            }
                        }
                    }

                    result[i][j] = (int) Math.floor(sum / count);
                }
            }
        }

        return result;
    }
}

