public class Solution {
    public boolean isPossibleToSplit(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();

        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        int n = nums.length;
        int halfN = n / 2;

        for (int num : nums) {
            if (countMap.get(num) > 0) {
                int remainingCount = countMap.get(num) - 1;

                // Try to split the array into two parts
                boolean canSplit = false;
                for (int i = 0; i < n; i++) {
                    if (nums[i] != num && countMap.get(nums[i]) > 0) {
                        int otherNum = nums[i];

                        // Update counts in the map
                        remainingCount--;
                        countMap.put(num, remainingCount);
                        countMap.put(otherNum, countMap.get(otherNum) - 1);

                        if (remainingCount >= 0 && canSplitArray(countMap)) {
                            return true;
                        }

                        // Backtrack: restore counts in the map
                        countMap.put(num, remainingCount + 1);
                        countMap.put(otherNum, countMap.get(otherNum) + 1);
                    }
                }
            }
        }

        return false;
    }

    private boolean canSplitArray(Map<Integer, Integer> countMap) {
        int n = countMap.size();
        for (int value : countMap.values()) {
            if (value < n / 2) {
                return false;
            }
        }
        return true;
    }
}

