public class Solution {
    public int minimumOperationsToWriteY(int[][] arr) {
        int n = arr.length;
        int centerRow = n / 2;

        // Check the diagonal from top-left to center
        boolean isDiagonal1Same = true;
        for (int i = 0; i <= centerRow; i++) {
            if (arr[i][i] != arr[centerRow][centerRow]) {
                isDiagonal1Same = false;
                break;
            }
        }

        // Check the diagonal from top-right to center
        boolean isDiagonal2Same = true;
        for (int i = 0; i <= centerRow; i++) {
            if (arr[i][n - i - 1] != arr[centerRow][centerRow]) {
                isDiagonal2Same = false;
                break;
            }
        }

        // Check the vertical line from center to bottom
        boolean isVerticalLineSame = true;
        for (int j = 0; j < n; j++) {
            if (arr[centerRow][j] != arr[centerRow][centerRow]) {
                isVerticalLineSame = false;
                break;
            }
        }

        // Check the values not belonging to Y
        boolean isNotYSame = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if ((i != centerRow || j != centerRow) && (j != n - i - 1 || i != centerRow)) {
                    if (arr[i][j] != arr[centerRow][centerRow]) {
                        isNotYSame = false;
                        break;
                    }
                }
            }
        }

        // Calculate the minimum operations
        int minOperations = 0;
        if (!isDiagonal1Same) {
            minOperations += n * n - (n + 1) / 2;
        }
        if (!isDiagonal2Same) {
            minOperations += n * n - (n + 1) / 2;
        }
        if (!isVerticalLineSame) {
            minOperations += n * n - (n + 1) / 2;
        }

        // If all values are the same, no operations needed
        if (isDiagonal1Same && isDiagonal2Same && isVerticalLineSame) {
            return 0;
        }

        // If not belonging to Y has different value than Y, subtract the number of cells in Y
        if (!isNotYSame) {
            minOperations -= n * n - (n + 1) / 2;
        }

        return Math.max(0, minOperations);
    }
}

