import java.util.*;

public class Solution {
    public int[] countPairsOfConnectableServers(int[][] edges, int signalSpeed) {
        int n = edges.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[] count = new int[n];
        boolean[] visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(graph, signalSpeed, i, -1, visited, count);
            }
        }

        return count;
    }

    private void dfs(List<List<Integer>> graph, int signalSpeed, int node, int parent, boolean[] visited, int[] count) {
        visited[node] = true;

        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                dfs(graph, signalSpeed, neighbor, node, visited, count);
            } else if (neighbor != parent) {
                int distanceToNeighbor = getDistance(graph, node, neighbor);

                if (distanceToNeighbor % signalSpeed == 0 && !hasCommonEdge(graph, node, neighbor)) {
                    count[node]++;
                    count[neighbor]++;
                }
            }
        }
    }

    private int getDistance(List<List<Integer>> graph, int u, int v) {
        Set<Integer> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[] {u, -1});
        visited.add(u);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            int parent = current[1];

            for (int neighbor : graph.get(node)) {
                if (!visited.contains(neighbor) && neighbor != parent) {
                    visited.add(neighbor);
                    queue.offer(new int[] {neighbor, node});
                }
            }

            if (node == v) {
                return getDistanceFromParent(graph, u, v);
            }
        }

        return -1;
    }

    private int getDistanceFromParent(List<List<Integer>> graph, int u, int v) {
        Set<Integer> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[] {u, -1});
        visited.add(u);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            int parent = current[1];

            for (int neighbor : graph.get(node)) {
                if (!visited.contains(neighbor) && neighbor != parent) {
                    visited.add(neighbor);
                    queue.offer(new int[] {neighbor, node});
                }
            }

            if (node == v) {
                return getDistanceFromParent(graph, u, v, parent);
            }
        }

        return -1;
    }

    private int getDistanceFromParent(List<List<Integer>> graph, int u, int v, int parent) {
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[] {u});
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];

            for (int neighbor : graph.get(node)) {
                if (neighbor != parent && !current.contains(neighbor)) {
                    queue.offer(new int[] {neighbor});
                }
            }

            if (node == v) {
                return current.length - 1;
            }
        }

        return -1;
    }

    private boolean hasCommonEdge(List<List<Integer>> graph, int u, int v) {
        Set<Integer> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[] {u});
        visited.add(u);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];

            for (int neighbor : graph.get(node)) {
                if (!visited.contains(neighbor) && !current.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.offer(new int[] {neighbor});
                }
            }

            if (node == v) {
                return true;
            }
        }

        return false;
    }
}

