public class Solution {
    public int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
        int[][] board = new int[8][8];

        // Place the white rook at position (a,b)
        board[a-1][b-1] = 1;

        // Place the white bishop at position (c,d)
        board[c-1][d-1] = 2;

        // Check if the black queen is in a position that can be captured by the rook
        if ((e == a && f >= b) || (f == b && e >= a)) {
            return 1;
        }

        // Check if the black queen is in a position that can be captured by the bishop
        else if (Math.abs(e - c) == Math.abs(f - d)) {
            return 1;
        }

        // If the black queen cannot be captured by either piece, we need to move one of them to capture it
        else {
            int minMoves = Integer.MAX_VALUE;

            // Check all possible moves for the rook
            for (int i = 0; i < 8; i++) {
                for (int j = 0; j < 8; j++) {
                    if (board[i][j] == 1) {
                        board[a-1][b-1] = 0;
                        board[i][j] = 1;

                        // Check all possible moves for the bishop
                        for (int k = 0; k < 8; k++) {
                            for (int l = 0; l < 8; l++) {
                                if (board[k][l] == 2) {
                                    board[c-1][d-1] = 0;
                                    board[k][l] = 2;

                                    // Check if the black queen can be captured by either piece
                                    if ((e == i && f >= j) || (f == j && e >= i)) {
                                        minMoves = Math.min(minMoves, 2);
                                    }
                                    else if (Math.abs(e - k) == Math.abs(f - l)) {
                                        minMoves = Math.min(minMoves, 2);
                                    }

                                    board[k][l] = 0;
                                }
                            }
                        }

                        board[a-1][b-1] = 1;
                    }
                }
            }

            // If the black queen cannot be captured by either piece after moving one of them, return -1
            if (minMoves == Integer.MAX_VALUE) {
                return -1;
            }

            // Return the minimum number of moves required to capture the black queen
            else {
                return minMoves;
            }
        }
    }
}

