public class Solution {
    public int findMaxNum(int k, int x) {
        int n = 0;
        while (true) {
            long sum = 0;
            for (int i = 1; i <= n; ++i) {
                String binary = Integer.toBinaryString(i);
                if ((binary.length() - 1 - binary.lastIndexOf('1') % x == 0)) {
                    sum += countSetBits(binary);
                }
            }
            if (sum > k) break;
            n++;
        }
        return n - 1;
    }

    private int countSetBits(String s) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') count++;
        }
        return count;
    }
}

