import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minimumDeletions(String word, int k) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : word.toCharArray()) {
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        int n = word.length();
        int[] maxFreq = new int[n];
        int[] minFreq = new int[n];

        maxFreq[0] = freq.get(word.charAt(0));
        for (int i = 1; i < n; i++) {
            maxFreq[i] = Math.max(maxFreq[i - 1], freq.get(word.charAt(i)));
        }

        minFreq[n - 1] = freq.get(word.charAt(n - 1));
        for (int i = n - 2; i >= 0; i--) {
            minFreq[i] = Math.min(minFreq[i + 1], freq.get(word.charAt(i)));
        }

        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int maxK = maxFreq[i];
            int minK = minFreq[i];

            if (maxK - minK > k) {
                continue;
            }
            int deletions = 0;
            for (char c : freq.keySet()) {
                int f = freq.get(c);
                if (f <= maxK && f >= minK - k) {
                    deletions += f;
                } else {
                    deletions += Math.max(0, f - (maxK + k));
                }
            }

            ans = Math.min(ans, word.length() - deletions);
        }

        return ans;
    }
}

