            if (s.substring(i, Math.min(i + a.length(), s.length())).equals(a)) {
                flagA[i] = true;
            }
            if (i - k >= 0 && s.substring(Math.max(0, i - k), Math.min(i + b.length(), s.length())).equals(b)) {
                flagB[i] = true;
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            if (flagA[i] && flagB[i]) {
                result.add(i);
            }
        }

        return result;
    }
