public class Solution {
    public int countMatchingSubarrays(int[] nums, int[] pattern) {
        int n = nums.length;
        int m = pattern.length;
        int count = 0;

        for (int i = 0; i <= n - m; i++) {
            boolean match = true;

            for (int j = 0; j < m; j++) {
                if (pattern[j] == -1) continue;

                if (nums[i + j + 1] > nums[i + j]) {
                    if (pattern[j] != nums[i + j + 1]) {
                        match = false;
                        break;
                    }
                } else if (nums[i + j + 1] < nums[i + j]) {
                    if (pattern[j] == nums[i + j + 1]) {
                        match = false;
                        break;
                    }
                } else {
                    if (pattern[j] != nums[i + j + 1]) {
                        match = false;
                        break;
                    }
                }
            }

            if (match) count++;
        }

        return count;
    }
}

