public class Solution {
    public int maxPartitionsAfterOperations(String s, int k) {
        int n = s.length();
        int[] charCount = new int[26];
        for (int i = 0; i < n; i++) {
            charCount[s.charAt(i) - 'a']++;
        }

        int maxK = 0;
        for (int count : charCount) {
            if (count > 0) {
                maxK++;
            }
        }

        if (maxK <= k) {
            return n;
        }

        int ans = 1;
        for (int i = 0; i < n; i++) {
            char[] chars = s.toCharArray();
            for (char c = 'a'; c <= 'z'; c++) {
                if (c == chars[i]) continue;
                chars[i] = c;
                int newK = 0;
                for (int j = 0; j < n; j++) {
                    charCount[chars[j] - 'a']++;
                    if (charCount[chars[j] - 'a'] > 0) {
                        newK++;
                    }
                }

                if (newK <= k) {
                    int partitions = 1;
                    for (int j = i + 1; j < n; j++) {
                        charCount[chars[j] - 'a']--;
                        if (charCount[chars[j] - 'a'] > 0) {
                            newK++;
                        }
                        while (newK > k && j >= i + 1) {
                            partitions++;
                            charCount[chars[j--] - 'a']--;
                            newK--;
                        }
                    }

                    ans = Math.max(ans, partitions);
                }

                for (int j = 0; j < n; j++) {
                    charCount[chars[j] - 'a']--;
                }
            }
        }

        return ans;
    }
}

