import java.util.*;

public class Solution {
    public long maximumValueSum(int[] nums, int k, int[][] edges) {
        int n = nums.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        long[] dp = new long[n];
        Arrays.fill(dp, -1);
        return dfs(0, -1, nums, k, graph, dp);
    }

    private long dfs(int node, int parent, int[] nums, int k, List<List<Integer>> graph, long[] dp) {
        if (dp[node] != -1) {
            return dp[node];
        }
        long max = 0;
        for (int child : graph.get(node)) {
            if (child == parent) continue;
            max += dfs(child, node, nums, k, graph, dp);
        }
        int xor = 0;
        for (int child : graph.get(node)) {
            if (child == parent) continue;
            xor ^= dfs(child, node, nums, k, graph, dp);
        }
        long res1 = max + (nums[node] ^ xor);
        long res2 = max + (nums[node] ^ (xor ^ k));
        return dp[node] = Math.max(res1, res2);
    }
}

