public class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        List<Integer> houses = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            houses.add(i);
        }
        if (x > y) {
            int temp = x;
            x = y;
            y = temp;
        }

        long[] result = new long[n];
        for (int k = 0; k < n; k++) {
            long count = 0;
            for (int i : houses) {
                if (i != x && i != y) {
                    int distance = Math.abs(i - x);
                    if (distance <= k) {
                        count += (long) (k - distance + 1) * (n - 1);
                    }
                } else if (i == x || i == y) {
                    int distance = Math.abs(x - y);
                    if (distance <= k) {
                        count += (long) (k - distance + 1) * (n - 1);
                    }
                }
            }
            result[k] = count;
        }

        return result;
    }
}

