import java.util.*;

public class Solution {
    public int[] stringIndices(String[] wordsContainer, String[] wordsQuery) {
        List<Integer> result = new ArrayList<>();

        for (String query : wordsQuery) {
            String maxSuffix = "";
            int maxIndex = -1;

            for (int i = 0; i < wordsContainer.length; i++) {
                String suffix = getCommonSuffix(query, wordsContainer[i]);

                if (!suffix.isEmpty() && (maxSuffix.isEmpty() || suffix.length() > maxSuffix.length())) {
                    maxSuffix = suffix;
                    maxIndex = i;
                } else if (!suffix.isEmpty() && suffix.length() == maxSuffix.length()) {
                    if (wordsContainer[i].length() < wordsContainer[maxIndex].length()) {
                        maxIndex = i;
                    }
                }
            }

            result.add(maxIndex);
        }

        return result.stream().mapToInt(i -> i).toArray();
    }

    private String getCommonSuffix(String s1, String s2) {
        int len = Math.min(s1.length(), s2.length());
        for (int i = 0; i < len; i++) {
            if (s1.charAt(len - i - 1) != s2.charAt(len - i - 1)) {
                return s1.substring(0, len - i);
            }
        }

        return s1.substring(0, len);
    }
}

