import java.util.*;

public class Solution {
    public int[] countOfPairs(int n, int x, int y) {
        List<Integer> distances = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            distances.add(i - 1);
        }

        if (x == y) {
            return distances.stream().mapToInt(Integer::intValue).toArray();
        }

        Queue<int[]> queue = new LinkedList<>();
        boolean[] visited = new boolean[n + 1];
        int[] distance = new int[n + 1];

        queue.offer(new int[]{x, 0});
        visited[x] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            int dist = current[1];

            if (node == y) {
                distance[node] = dist;
            }

            for (int i = Math.max(1, node - 1); i <= Math.min(n, node + 1); i++) {
                if (!visited[i]) {
                    queue.offer(new int[]{i, dist + 1});
                    visited[i] = true;
                    distance[i] = dist + 1;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            distances.set(i, distance[y]);
        }

        return distances.stream().mapToInt(Integer::intValue).toArray();
    }
}

