            if (nums[i] != 0) {
                pq.offer(new int[]{nums[i], i});
            }
        }

        int m = changeIndices.length;
        int s = 1;
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            if (top[0] == 0 && top[1] != changeIndices[s - 1]) {
                return -1;
            }
            if (nums[top[1]] > 0) {
                nums[top[1]]--;
                if (nums[top[1]] == 0) {
                    pq.offer(new int[]{top[0], top[1]});
                }
            } else if (changeIndices[s - 1] == top[1]) {
                s++;
            }
        }

        return m;
    }
}

