public class Solution {
    public long maximumStrength(int[] nums, int k) {
        int n = nums.length;
        long[][] dp = new long[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, k); j++) {
                dp[i][j] = -1000000000L;
            }
        }

        long[] prefixSum = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixSum[i] = prefixSum[i - 1] + nums[i - 1];
        }

        dp[0][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = Math.min(i, k); j >= 1; j--) {
                long strength = prefixSum[i] * (i + 1) - prefixSum[i - j] * (j);
                dp[i][j] = Math.max(dp[i][j], dp[i - 1][j]);
                if (j < i && dp[i - j - 1][j + 1] != -1000000000L) {
                    long tempStrength = prefixSum[i] * (i + 1) - prefixSum[i - j - 1] * (j + 1);
                    dp[i][j] = Math.max(dp[i][j], tempStrength + dp[i - j - 1][j + 1]);
                }
            }
        }

        long maxStrength = -1000000000L;
        for (int i = 1; i <= k; i++) {
            maxStrength = Math.max(maxStrength, dp[n][i]);
        }
        return maxStrength;
    }
}

