public class Solution {
    public int sumOfPower(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        long mod = (long) 1e9 + 7;
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        return helper(map, k, 0, 1, mod);
    }

    private int helper(Map<Integer, Integer> map, int target, int sum, long power, long mod) {
        if (target == 0) {
            return (int) ((power % mod));
        }
        if (map.containsKey(target)) {
            int count = map.get(target);
            for (int i = 1; i <= count; i++) {
                power *= i;
                power %= mod;
                sum += helper(map, target - target, sum + 1, power, mod);
                power /= i;
                power %= mod;
            }
        } else {
            return 0;
        }
        return (int) ((power % mod));
    }
}

