public class Solution {
    public long minimumCost(int[] nums, int k, int dist) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int i = 0; i < nums.length; i++) {
            set.add(i);
        }
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        long ans = Long.MAX_VALUE;
        int cost = nums[0];
        for (int i = 0; i < k - 1; i++) {
            if (!set.isEmpty()) {
                Integer nextIndex = set.higher(set.first());
                if (nextIndex != null) {
                    pq.offer(new int[]{nextIndex, nums[nextIndex]});
                    set.remove(nextIndex);
                }
            }
            while (!pq.isEmpty() && !set.isEmpty()) {
                int[] top = pq.poll();
                Integer nextIndex = set.higher(top[0]);
                if (nextIndex == null || nextIndex - top[0] > dist) {
                    break;
                } else {
                    cost += nums[nextIndex];
                    set.remove(nextIndex);
                    pq.offer(new int[]{nextIndex, nums[nextIndex]});
                }
            }
            ans = Math.min(ans, cost);
        }
        return ans;
    }
}

