public class Solution {
    public int sumSubseqWidths(int[] nums) {
        Arrays.sort(nums);
        long mod = (long) 1e9 + 7;
        Map<Integer, Long> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            map.put(nums[i], map.getOrDefault(nums[i], 0L) + pow(i));
        }
        long ans = 0;
        for (int i = 0; i < nums.length; i++) {
            int left = nums[i];
            long right = 0;
            for (int j = i + 1; j < nums.length; j++) {
                right += map.get(nums[j]);
            }
            ans = (ans + pow(i) * left % mod * right % mod) % mod;
        }
        return (int) (ans % mod);
    }

    private long pow(int n) {
        if (n == 0) return 1;
        long res = pow(n / 2);
        if (n % 2 != 0) return res * res + 1;
        else return res * res;
    }
}

