public class Solution {
    public int maxEqualScore(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> memo = new HashMap<>();

        return Math.max(
            helper(nums, 0, 0, memo),
            helper(nums, 1, 0, memo)
        );
    }

    private int helper(int[] nums, int i, int score, Map<Integer, Integer> memo) {
        if (i >= nums.length - 1) return 0;

        int key = i * 10000 + score;
        if (memo.containsKey(key)) return memo.get(key);

        int maxOps = 0;
        for (int j = Math.max(i, 2); j <= Math.min(nums.length - 1, nums.length - i - 1); ++j) {
            int newScore = score + nums[i] + nums[j];
            if (i == 0 && j == nums.length - 1) continue;

            maxOps = Math.max(maxOps, helper(nums, j + 1, newScore, memo));
        }

        memo.put(key, maxOps);
        return maxOps;
    }
}

