public class Solution {
    public long largestSquareArea(int[][] bottomLeft, int[][] topRight) {
        Set<String> set = new HashSet<>();
        for (int i = 0; i < bottomLeft.length; i++) {
            for (int j = 0; j < bottomLeft.length; j++) {
                if (i != j && doIntersect(bottomLeft[i], topRight[i], bottomLeft[j], topRight[j])) {
                    String key = getKey(bottomLeft[i][0], bottomLeft[i][1], bottomLeft[j][0], bottomLeft[j][1]);
                    set.add(key);
                }
            }
        }

        long maxArea = 0;
        for (String s : set) {
            int[] x = getXY(s);
            int minX = Math.min(x[0], x[2]), maxX = Math.max(x[0], x[2]);
            int minY = Math.min(x[1], x[3]), maxY = Math.max(x[1], x[3]);

            long area = (long) (maxX - minX + 1) * (maxY - minY + 1);
            maxArea = Math.max(maxArea, area);
        }
        return maxArea;
    }

    private boolean doIntersect(int[] a, int[] b, int[] c, int[] d) {
        if (Math.min(a[0], c[0]) <= Math.max(b[0], d[0]) && Math.min(a[1], c[1]) <= Math.max(b[1], d[1])) return true;
        else return false;
    }

    private String getKey(int a, int b, int c, int d) {
        return a + "," + b + "," + c + "," + d;
    }

    private int[] getXY(String s) {
        String[] parts = s.split(",");
        return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]), Integer.parseInt(parts[3])};
    }
}

