public class Solution {
    public boolean canSortArray(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - 1; j++) {
                if (nums[j] != nums[j + 1]) continue;
                if (countBits(nums[j]) != countBits(nums[j + 1])) return false;
            }
        }
