public class Solution {
    public int countHighestScoreNodes(int[] parents) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < parents.length; i++) {
            if (!graph.containsKey(parents[i])) {
                graph.put(parents[i], new ArrayList<>());
            }
            graph.get(parents[i]).add(i);
        }

        int[] sizes = new int[parents.length];
        dfs(graph, -1, 0, sizes);

        long maxProduct = 0;
        int countMax = 0;

        for (int i = 0; i < parents.length; i++) {
            if (graph.get(i).isEmpty()) {
                continue;
            }
            long product = 1;
            for (int j : graph.get(i)) {
                product *= sizes[j];
            }
            if (product > maxProduct) {
                maxProduct = product;
                countMax = 1;
            } else if (product == maxProduct) {
                countMax++;
            }
        }

        return countMax;
    }

    private int dfs(Map<Integer, List<Integer>> graph, int parent, int node, int[] sizes) {
        if (!graph.containsKey(node)) {
            return 0;
        }
        int size = 1 + dfs(graph, node, graph.get(node).get(0), sizes);
        for (int i : graph.get(node)) {
            if (i != graph.get(node).get(0)) {
                size += dfs(graph, node, i, sizes);
            }
        }
        sizes[node] = size;
        return size;
    }
}

