import java.util.*;

public class Solution {
    public int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[] distance = new int[n];
        Arrays.fill(distance, -1);
        distance[0] = 0;
        PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        queue.offer(new int[]{0, 0});
        while (!queue.isEmpty()) {
            int[] node = queue.poll();
            for (int neighbor : graph.get(node[1])) {
                if (distance[neighbor] == -1 || distance[node[1]] + 1 < distance[neighbor]) {
                    distance[neighbor] = distance[node[1]] + 1;
                    queue.offer(new int[]{distance[neighbor], neighbor});
                }
            }
        }

        int[] time = new int[n];
        for (int i = 0; i < n; i++) {
            if (i != 0) {
                time[i] = distance[i] * 2 + 1;
                int resendTime = 0;
                while (resendTime <= time[i]) {
                    resendTime += patience[i];
                }
                time[i] = Math.min(time[i], resendTime);
            }
        }

        int maxTime = 0;
        for (int t : time) {
            maxTime = Math.max(maxTime, t);
        }
        return maxTime + 1;
    }
}

