        if (startPos[1] < homePos[1]) {
            for (int i = startPos[1]; i <= homePos[1]; i++) {
                cost += colCosts[i];
            }
        } else if (startPos[1] > homePos[1]) {
            for (int i = startPos[1]; i >= homePos[1]; i--) {
                cost += colCosts[i];
