import java.util.*;

public class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        UnionFind uf = new UnionFind(n);
        for (int[] restriction : restrictions) {
            uf.union(restriction[0], restriction[1]);
        }
        boolean[] result = new boolean[requests.length];
        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];
            if (!uf.isSameGroup(u, v)) {
                uf.union(u, v);
                result[i] = true;
            } else {
                for (int[] restriction : restrictions) {
                    if (uf.find(restriction[0]) == uf.find(v) || uf.find(restriction[1]) == uf.find(u)) {
                        result[i] = false;
                        break;
                    }
                }
                if (!result[i]) continue;

                int[] groupU = getGroup(uf, u);
                int[] groupV = getGroup(uf, v);

                for (int[] restriction : restrictions) {
                    if ((restriction[0] == groupU[0] && restriction[1] == groupV[1])
                            || (restriction[0] == groupV[0] && restriction[1] == groupU[1])) {
                        result[i] = false;
                        break;
                    }
                }
            }
        }
        return result;
    }

    private int[] getGroup(UnionFind uf, int u) {
        while (uf.find(u) != u) {
            u = uf.find(u);
        }
        return new int[]{u, uf.get(u)};
    }

    class UnionFind {
        int[] parent;
        int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }

