public class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceWord(board, i, j, word)) {
                    return true;
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceWord(board, i, j, new StringBuilder(word).reverse().toString())) {
                    return true;
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceWord(board, i, j, word)) {
                    return true;
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (canPlaceWord(board, i, j, new StringBuilder(word).reverse().toString())) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canPlaceWord(char[][] board, int x, int y, String word) {
        int m = board.length;
        int n = board[0].length;

        if (x + word.length() > m || y + word.length() > n) {
            return false;
        }

        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (board[x][y + i] != ' ' && board[x][y + i] != c) {
                return false;
            }
            if (board[x + i][y] != ' ' && board[x + i][y] != c) {
                return false;
            }
        }

        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (board[x][y + i] == '#' || board[x + i][y] == '#') {
                return false;
            }
        }

        return true;
    }
}

