public class Solution {
    public int minimizedMaximum(int n, int[] q) {
        int left = 1;
        int right = Integer.MAX_VALUE / n;

        while (left < right) {
            int mid = left + (right - left) / 2;

            long sum = 0;
            for (int quantity : q) {
                sum += Math.ceil((double) quantity / mid);
            }

            if (sum <= n) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
}

