        int minIndex = 0;
        int maxIndex = 0;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < nums[minIndex]) {
                minIndex = i;
            }
            else if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
