import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }

        Map<Long, Integer> prefixSumCountMap = new HashMap<>();
        prefixSumCountMap.put(0L, 1);

        long currentPrefixSum = 0;
        int maxWays = 0;

        for (int i = 0; i < n; i++) {
            currentPrefixSum += nums[i];

            if (prefixSumCountMap.containsKey(currentPrefixSum)) {
                maxWays = Math.max(maxWays, prefixSumCountMap.get(currentPrefixSum));
            }

            long diff = sum - currentPrefixSum;
            if (diff == k || diff == -k) {
                maxWays++;
            }

            prefixSumCountMap.put(currentPrefixSum, prefixSumCountMap.getOrDefault(currentPrefixSum, 0) + 1);
        }

        int[] modifiedNums = new int[n];
        System.arraycopy(nums, 0, modifiedNums, 0, n);

        for (int i = 0; i < n; i++) {
            if (modifiedNums[i] != k) {
                modifiedNums[i] = k;

                long currentPrefixSumModified = 0;
                Map<Long, Integer> prefixSumCountMapModified = new HashMap<>();
                prefixSumCountMapModified.put(0L, 1);

                for (int j = 0; j < n; j++) {
                    currentPrefixSumModified += modifiedNums[j];

                    if (prefixSumCountMapModified.containsKey(currentPrefixSumModified)) {
                        maxWays = Math.max(maxWays, prefixSumCountMapModified.get(currentPrefixSumModified));
                    }

                    long diff = sum - currentPrefixSumModified;
                    if (diff == k || diff == -k) {
                        maxWays++;
                    }

                    prefixSumCountMapModified.put(currentPrefixSumModified, prefixSumCountMapModified.getOrDefault(currentPrefixSumModified, 0) + 1);
                }

                modifiedNums[i] = nums[i];
            }
        }

        return maxWays;
    }
}

