import java.util.*;

public class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        Queue<int[]> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();

        queue.offer(new int[]{start, 0});
        visited.add(start);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int steps = current[1];

            if (x == goal) return steps;

            for (int num : nums) {
                int nextX = x + num;
                if (nextX <= 1000 && !visited.contains(nextX)) {
                    queue.offer(new int[]{nextX, steps + 1});
                    visited.add(nextX);
                }

                nextX = x - num;
                if (nextX >= 0 && nextX <= 1000 && !visited.contains(nextX)) {
                    queue.offer(new int[]{nextX, steps + 1});
                    visited.add(nextX);
                }

                nextX = x ^ num;
                if (!visited.contains(nextX)) {
                    queue.offer(new int[]{nextX, steps + 1});
                    visited.add(nextX);
                }
            }
        }

        return -1;
    }
}

