public class Solution {
    public int minimumDifference(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length / 2;
        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < n; i++) {
            sum1 += nums[i];
        }
        for (int i = n; i < nums.length; i++) {
            sum2 += nums[i];
        }
        int minDiff = Math.abs(sum1 - sum2);
        for (int i = n + 1; i < nums.length; i++) {
            sum1 -= nums[i - n - 1];
            sum2 += nums[i];
            minDiff = Math.min(minDiff, Math.abs(sum1 - sum2));
        }
        return minDiff;
    }
}

