public class Solution {
    public int countMaxOrSubsets(int[] nums) {
        int n = nums.length;
        int maxOr = 0;
        for (int i : nums) {
            maxOr |= i;
        }

        int res = 0;
        backtrack(nums, new boolean[n], 0, maxOr, res);
        return res;
    }

    private void backtrack(int[] nums, boolean[] visited, int index, int target, int res) {
        if (index == nums.length) {
            if ((target & nums[index - 1]) == nums[index - 1]) {
                res++;
            }
            return;
        }

        backtrack(nums, visited, index + 1, target | nums[index], res);
        backtrack(nums, visited, index + 1, target, res);
    }
}

