import java.util.*;

public class Solution {
    public String longestSubsequenceRepeatedK(String s, int k) {
        int n = s.length();
        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = i; j < n; j++) {
                sb.append(s.charAt(j));
                if (!map.containsKey(sb.toString())) {
                    map.put(sb.toString(), 1);
                } else {
                    int count = map.get(sb.toString());
                    map.put(sb.toString(), count + 1);
                }
            }
        }

        List<String> list = new ArrayList<>(map.keySet());
        Collections.sort(list, (a, b) -> Integer.compare(b.length(), a.length()));

        for (String str : list) {
            if (str.length() % k == 0 && map.get(str) >= k) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < str.length(); i++) {
                    sb.append(str.charAt(i));
                }
                while (sb.length() <= n && s.contains(sb.toString())) {
                    if (s.indexOf(sb.toString()) == 0) {
                        return sb.toString();
                    } else {
                        sb.delete(0, 1);
                    }
                }
            }
        }

        return "";
    }
}

