        int sign = 1;
        int num = 0;
        for (char c : s.toCharArray()) {
            if (c == '+') {
                result += sign * num;
                sign = 1;
                num = 0;
            } else if (c == '*') {
                result += sign * num;
                sign = 1;
                num = 0;
            } else {
                num = num * 10 + c - '0';
            }
        }
        return result + sign * num;
    }

    private boolean isArithmeticCorrect(String s, int answer) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '+') {
                String left = s.substring(0, i);
                String right = s.substring(i + 1);
                int leftValue = calculate(left);
                int rightValue = answer - leftValue;
                if (!isArithmeticCorrect(right, rightValue)) {
                    return false;
                }
            } else if (s.charAt(i) == '*') {
                String left = s.substring(0, i);
                String right = s.substring(i + 1);
                int leftValue = calculate(left);
                int rightValue = answer / leftValue;
                if (!isArithmeticCorrect(right, rightValue)) {
                    return false;
                }
            }
        }
        return true;
    }
}

