public class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        long sum = 0;
        for (int roll : rolls) {
            sum += roll;
        }

        long totalSum = (long)mean * (n + rolls.length);
        long diff = totalSum - sum;

        if (diff < 1 || diff % (n + rolls.length) != 0) {
            return new int[0];
        }

        int avgDiff = (int)(diff / (n + rolls.length));
        int extraCount = (int)((diff % (n + rolls.length)) > 0 ? 1 : 0);

        int[] missingRolls = new int[n];
        for (int i = 0; i < n; i++) {
            if (i < n - extraCount) {
                missingRolls[i] = avgDiff;
            } else {
                missingRolls[i] = avgDiff + 1;
            }
        }

        return missingRolls;
    }
}

