import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int maxTwoEvents(int[][] events) {
        Arrays.sort(events, Comparator.comparingInt(a -> a[0]));

        int n = events.length;
        int[] dp = new int[n];
        dp[0] = events[0][2];

        for (int i = 1; i < n; i++) {
            if (events[i][0] > events[i - 1][1]) {
                dp[i] = Math.max(dp[i], events[i][2]);
            }

            int j = Arrays.binarySearch(events, new int[] {events[i - 1][1] + 1, Integer.MAX_VALUE, Integer.MIN_VALUE}, Comparator.comparingInt(a -> a[0]));
            if (j < 0) {
                j = ~j;
            }

            if (j > 0 && events[j - 1][1] >= events[i][0]) {
                dp[i] = Math.max(dp[i], dp[j - 1] + events[i][2]);
            }
        }

        int maxSum = Integer.MIN_VALUE;
        for (int i : dp) {
            maxSum = Math.max(maxSum, i);
        }

        return maxSum;
    }
}

