public class Solution {
    public long kMirror(int k, int n) {
        List<Integer> res = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            String numStr = Integer.toString(i);
            if (!numStr.startsWith("0")) {
                StringBuilder sb = new StringBuilder(numStr);
                String revNumStr = sb.reverse().toString();
                boolean isPalindrome = true;
                int baseKNum = 0;
                for (int j = 0; j < Math.min(k, numStr.length()); j++) {
                    if (Character.getNumericValue(numStr.charAt(j)) != Character.getNumericValue(revNumStr.charAt(j))) {
                        isPalindrome = false;
                        break;
                    }
                    baseKNum += Character.getNumericValue(numStr.charAt(j)) * Math.pow(k, j);
                }
                if (isPalindrome) {
                    res.add(baseKNum);
                }
            }
        }
        long sum = 0;
        for (int num : res) {
            sum += num;
        }
        return sum;
    }
}

