public class Solution {
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 1; i < n; i++) {
            graph[parents[i]].add(i);
        }

        int[] ans = new int[n];
        Arrays.fill(ans, -1);

        for (int i = 0; i < n; i++) {
            if (ans[i] != -1) continue;
            Set<Integer> set = new HashSet<>();
            dfs(graph, i, nums, set);
            int min = 1;
            while (set.contains(min)) min++;
            ans[i] = min;
        }

        return ans;
    }

    private void dfs(List<Integer>[] graph, int node, int[] nums, Set<Integer> set) {
        set.add(nums[node]);
        for (int child : graph[node]) {
            dfs(graph, child, nums, set);
        }
    }
}

