public class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        int length = 0;
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        while (head != null) {
            length++;
            if (length % 2 == 0) {
                ListNode prev = dummy;
                for (int i = 1; i <= length / 2; i++) {
                    ListNode nextNode = head.next;
                    ListNode curr = head;
                    head = head.next;
                    curr.next = prev.next;
                    prev.next = curr;
                    if (i == length / 2) {
                        prev.next.next = null;
                    }
                }
            } else {
                ListNode end = dummy;
                for (int i = 1; i <= length - 1; i++) {
                    end = end.next;
                }
                end.next = head;
            }
        }
        return dummy.next;
    }
}

