                while (left >= 0 && s.charAt(left) != '|') {
                    left--;
                }
                int right = i + 1;
                while (right < n && s.charAt(right) != '|') {
                    right++;
                }
                for (int j = 0; j < queries.length; j++) {
                    if (queries[j][0] <= left && right <= queries[j][1]) {
                        answer[j]++;
                    }
                }
            }
        }
