import java.util.*;

public class Solution {
    public int[][] validArrangement(int[][] pairs) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] pair : pairs) {
            graph.computeIfAbsent(pair[0], k -> new ArrayList<>()).add(pair[1]);
            graph.computeIfAbsent(pair[1], k -> new ArrayList<>()).add(pair[0]);
        }

        int start = -1;
        for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
            if (entry.getValue().size() % 2 == 1) {
                if (start != -1) return null; // cycle
                start = entry.getKey();
            }
        }

        Queue<int[]> queue = new LinkedList<>();
        for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
            if (entry.getValue().size() % 2 == 0) {
                int[] pair = {entry.getKey(), entry.getValue().get(0)};
                queue.offer(pair);
            }
        }

        int[][] result = new int[pairs.length][];
        while (!queue.isEmpty()) {
            int[] pair = queue.poll();
            result[0] = pair;
            graph.get(pair[1]).remove(graph.get(pair[1]).indexOf(pair[0]));
            if (graph.get(pair[1]).size() == 0) continue;

            int nextStart = graph.get(pair[1]).get(0);
            for (int i = 1; i < pairs.length; i++) {
                result[i] = new int[]{nextStart, pair[1]};
                queue.offer(result[i]);
                if (graph.get(nextStart).size() == 0) break;
                nextStart = graph.get(nextStart).get(0);
            }
        }

        return result;
    }
}

