import com.github.leetcode.ListNode;

public class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        int prevVal = 0, currVal = dummy.val;
        int prevType = -1, currType = getNodeType(dummy);
        int minDistance = Integer.MAX_VALUE, maxDistance = 0;
        int index = 0;

        for (ListNode node = dummy.next; node != null; node = node.next) {
            if (currVal < prevVal && currVal < node.next.val) {
                currType = 1;
            } else if (currVal > prevVal && currVal > node.next.val) {
                currType = 2;
            }
            if (prevType != -1 && currType != -1 && prevType != currType) {
                minDistance = Math.min(minDistance, index - criticalPoints.get(prevType));
                maxDistance = Math.max(maxDistance, index - criticalPoints.get(prevType));
            }
            prevVal = currVal;
            prevType = currType;
            currVal = node.val;
            index++;
        }

        if (minDistance == Integer.MAX_VALUE) {
            return new int[]{-1, -1};
        } else {
            return new int[]{minDistance, maxDistance};
        }
    }

    private int getNodeType(ListNode node) {
        if (node.next != null && node.val > node.prev.val && node.val > node.next.val) {
            return 2;
        } else if (node.next != null && node.val < node.prev.val && node.val < node.next.val) {
            return 1;
        }
        return -1;
    }

    private int[] criticalPoints = new int[3];
}

