public class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    int height = dfs(grid, visited, i, j);
                    count += height * (height + 1) / 2;
                }
            }
        }

        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    int height = dfs(grid, visited, i, j);
                    count += height * (height + 1) / 2;
                }
            }
        }

        return count;
    }

    private int dfs(int[][] grid, boolean[][] visited, int r, int c) {
        if (!isValid(r, c, grid.length, grid[0].length)) {
            return 0;
        }

        if (visited[r][c]) {
            return 0;
        }

        if (grid[r][c] == 0) {
            return 0;
        }

        visited[r][c] = true;

        int count = 1;

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            count += dfs(grid, visited, nr, nc);
        }

        return count;
    }

    private boolean isValid(int r, int c, int m, int n) {
        if (r < 0 || r >= m || c < 0 || c >= n) {
            return false;
        }
        return true;
    }
}

