public class Solution {
    public String getDirections(TreeNode root, int startValue, int destValue) {
        Map<Integer, List<TreeNode>> map = new HashMap<>();
        dfs(root, null, map);

        List<String> path1 = getPath(map.get(startValue), destValue);
        List<String> path2 = getPath(map.get(destValue), startValue);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Math.min(path1.size(), path2.size()); i++) {
            if (!path1.get(i).equals(path2.get(i))) break;
            sb.append("U");
        }
        sb.append(path1.subList(Math.min(path1.size(), path2.size()), path1.size()));

        return sb.toString();
    }

    private void dfs(TreeNode node, TreeNode parent, Map<Integer, List<TreeNode>> map) {
        if (node == null) return;
        if (!map.containsKey(node.val)) {
            map.put(node.val, new ArrayList<>());
        }
        if (parent != null) {
            map.get(parent.val).add(node);
        }
        dfs(node.left, node, map);
        dfs(node.right, node, map);
    }

    private List<String> getPath(List<TreeNode> nodes, int target) {
        for (TreeNode node : nodes) {
            if (node.val == target) return getDirections(node.val + "", target + "");
        }
        return new ArrayList<>();
    }

    private String getDirections(int start, int end) {
        StringBuilder sb = new StringBuilder();
        while (start != end) {
            if (end > start) {
                sb.append("R");
                end /= 2;
            } else {
                sb.append("L");
                start /= 2;
            }
        }
        return sb.toString();
    }
}

