import java.util.*;

public class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0] - 1).add(edge[1] - 1);
            graph.get(edge[1] - 1).add(edge[0] - 1);
        }

        int[][] dist = new int[n][2];
        Arrays.fill(dist[0], Integer.MAX_VALUE / 2);
        dist[0][0] = 0;
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            for (int next : graph.get(cur[0])) {
                if (dist[next][1] == Integer.MAX_VALUE / 2) {
                    dist[next][1] = Math.max(dist[cur[0]][1], dist[cur[0]][0]) + time;
                    queue.offer(new int[]{next, dist[next][1]});
                }
                if (dist[next][0] > dist[cur[0]][1] + change) {
                    dist[next][0] = dist[cur[0]][1] + change + time;
                    queue.offer(new int[]{next, dist[next][0]});
                }
            }
        }

        return dist[n - 1][1];
    }
}

