public class Solution {
    public int maxConsecutiveAnswers(String answerKey, int k) {
        char[] key = answerKey.toCharArray();
        int n = key.length;
        int[] prefixSumT = new int[n + 1];
        int[] prefixSumF = new int[n + 1];

        for (int i = 0; i < n; i++) {
            if (key[i] == 'T') {
                prefixSumT[i + 1] = prefixSumT[i] + 1;
                prefixSumF[i + 1] = prefixSumF[i];
            } else {
                prefixSumT[i + 1] = prefixSumT[i];
                prefixSumF[i + 1] = prefixSumF[i] + 1;
            }
        }

        int maxConsecutive = Math.min(prefixSumT[n], prefixSumF[n]);
        for (int i = 0; i < n; i++) {
            if (i - k >= 0) {
                maxConsecutive = Math.max(maxConsecutive, Math.min(prefixSumT[i] - prefixSumT[i - k], prefixSumF[i] - prefixSumF[i - k]));
            } else {
                maxConsecutive = Math.max(maxConsecutive, Math.min(prefixSumT[i], prefixSumF[i]));
            }
        }

        return maxConsecutive;
    }
}

